// isNameDefinition reports whether the identifier occurrence is a
// definition site (var spec, :=, range variable, parameter, func/type
// name, label) rather than a use.
func isNameDefinition(id *ast.Ident, parent ast.Node) bool {
	switch p := parent.(type) {
	case *ast.ValueSpec:
		for _, nm := range p.Names {
			if nm == id {
				return true
			}
		}
	case *ast.AssignStmt:
		if p.Tok == token.DEFINE {
			for _, lhs := range p.Lhs {
				if lhs == id {
					return true
				}
			}
		}
	case *ast.RangeStmt:
		if p.Key == id || p.Value == id {
			return true
		}
	case *ast.Field:
		for _, nm := range p.Names {
			if nm == id {
				return true
			}
		}
	case *ast.FuncDecl:
		return p.Name == id
	case *ast.TypeSpec:
		return p.Name == id
	case *ast.LabeledStmt:
		return p.Label == id
	case *ast.ImportSpec:
		return p.Name == id
	}
	return false
}

