// parseFilesFromResponse splits a raw LLM response into module-relative
// path -> Go source. Markdown fences are stripped; chatter before the
// first marker is ignored. Paths are validated with the same jail
// rules the sandbox enforces.
func parseFilesFromResponse(resp string) (map[string]string, error) {
	resp = stripCodeFences(resp)
	files := make(map[string]string)
	var cur string
	var sb strings.Builder
	flush := func() {
		if cur != "" {
			files[cur] = strings.Trim(sb.String(), "\n") + "\n"
			sb.Reset()
		}
	}
	for _, line := range strings.Split(resp, "\n") {
		if m := fileMarkerRe.FindStringSubmatch(strings.TrimSpace(line)); m != nil {
			flush()
			path := filepath.Clean(m[1])
			if err := validCandidatePath(path); err != nil {
				return nil, fmt.Errorf("invalid file path %q: %w", m[1], err)
			}
			cur = path
			continue
		}
		if cur == "" {
			continue
		}
		sb.WriteString(line)
		sb.WriteByte('\n')
	}
	flush()
	if len(files) == 0 {
		return nil, fmt.Errorf("no === FILE: <path> === blocks found")
	}
	return files, nil
}

// pickBest applies safety penalties to the MCTS-ranked nodes and
// returns the highest safety-adjusted fitness (ID tiebreak).
func pickBest(ranked []synthesis.CandidateNode, penalties []int) scoredCandidate {
	scored := make([]scoredCandidate, 0, len(ranked))
	for _, node := range ranked {
		pen, idx := 0, -1
		if i, ok := survivorIndexOf(node.ID); ok && i < len(penalties) {
			pen, idx = penalties[i], i
		}
		final := node.Score - float64(pen)
		allocs := "n/a"
		if len(node.Errors) == 0 {
			allocs = fmt.Sprintf("%d", node.Metrics.AllocsPerOp)
		}
		scored = append(scored, scoredCandidate{node: node, final: final, index: idx})
		fmt.Printf("   %s: raw=%.1f safety=-%d final=%.1f allocs/op=%s errors=%d\n",
			node.ID, node.Score, pen, final, allocs, len(node.Errors))
	}
	sort.Slice(scored, func(a, b int) bool {
		if scored[a].final != scored[b].final {
			return scored[a].final > scored[b].final
		}
		return scored[a].node.ID < scored[b].node.ID
	})
	return scored[0]
}

// pointerReceiver converts the first value-receiver method in the file
// to a pointer receiver: `func (s T) M()` becomes `func (s *T) M()`.
// Pointer receivers avoid copying the receiver on every call, which
// also avoids the heap allocation a copying call can cause. Methods
// already on pointer receivers are skipped. One method per call.
//
// Caveat: this changes T's method set (M moves from T to *T), which
// can break interface satisfaction elsewhere. The validation gate
// discards the mutation if anything stops compiling or tests fail.
func pointerReceiver(f *ast.File) bool {
	for _, decl := range f.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok || fn.Recv == nil || len(fn.Recv.List) != 1 {
			continue
		}
		recv := fn.Recv.List[0]
		id, ok := recv.Type.(*ast.Ident)
		if !ok || id.Name == "" || id.Name == "_" {
			continue
		}
		recv.Type = &ast.StarExpr{X: id}
		return true
	}
	return false
}

