// stringBuilder rewrites
//
//	var s string
//	for ... { s += part }
//
// into
//
//	var s strings.Builder
//	for ... { s.WriteString(part) }
//
// and rewrites every remaining load of s into s.String(). It bails out
// (leaving the file untouched) if s is redefined anywhere in the
// function, assigned any other way, address-taken, or referenced
// inside an `s += ...` right-hand side. Because the variable keeps its
// name and every use is converted, closures over s stay correct.
func stringBuilder(f *ast.File) bool {
	changed := false
	for _, decl := range f.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok || fn.Body == nil {
			continue
		}
		spec, nameIdent := findStringVar(fn.Body)
		if spec == nil {
			continue
		}
		if rewriteConcatLoop(f, fn, spec, nameIdent) {
			changed = true
		}
	}
	return changed
}

// stripCodeFences removes markdown fence lines LLMs like to wrap code
// in; the file markers carry the structure.
func stripCodeFences(s string) string {
	lines := strings.Split(s, "\n")
	out := lines[:0]
	for _, line := range lines {
		t := strings.TrimSpace(line)
		if t == "```" || t == "```go" {
			continue
		}
		out = append(out, line)
	}
	return strings.Join(out, "\n")
}

// survivorIndexOf resolves a ranked node's ID back to its index in the
// survivor/penalty slices. synthesis.EvaluateCandidatesRanked names
// nodes "candidate-N" in survivor order, so the penalty travels with
// the candidate no matter how evaluation reorders them.
func survivorIndexOf(id string) (int, bool) {
	const prefix = "candidate-"
	if !strings.HasPrefix(id, prefix) {
		return 0, false
	}
	n, err := strconv.Atoi(strings.TrimPrefix(id, prefix))
	if err != nil || n < 0 {
		return 0, false
	}
	return n, true
}

// tryMutation parses every non-test Go file, applies m, and returns
// the rewritten file set. Files the mutation did not touch keep their
// original source. A false second return means nothing changed.
func tryMutation(files map[string]string, m mutation) (map[string]string, bool) {
	out := cloneFiles(files)
	changed := false
	for path, src := range out {
		if !isTunableFile(path) {
			continue
		}
		fset := token.NewFileSet()
		f, err := parser.ParseFile(fset, path, src, parser.ParseComments)
		if err != nil {
			return nil, false
		}
		if !m.apply(f) {
			continue
		}
		var buf bytes.Buffer
		if err := format.Node(&buf, fset, f); err != nil {
			return nil, false
		}
		out[path] = buf.String()
		changed = true
	}
	return out, changed
}

func unquote(s string) string {
	if u, err := strconv.Unquote(s); err == nil {
		return u
	}
	return strings.Trim(s, `"`)
}

// validCandidatePath mirrors the sandbox jail: module-relative .go
// paths only, no absolute paths, no ".." escapes.
func validCandidatePath(p string) error {
	if p == "" {
		return fmt.Errorf("empty path")
	}
	if filepath.IsAbs(p) {
		return fmt.Errorf("absolute paths not allowed")
	}
	if p == ".." || strings.HasPrefix(p, ".."+string(filepath.Separator)) {
		return fmt.Errorf("path escapes module")
	}
	if filepath.Ext(p) != ".go" {
		return fmt.Errorf("not a Go file")
	}
	return nil
}

// varSliceDecl matches `var <name> []T` (no initializer) and returns
// the name and element type.
func varSliceDecl(stmt ast.Stmt) (string, ast.Expr) {
	ds, ok := stmt.(*ast.DeclStmt)
	if !ok {
		return "", nil
	}
	gd, ok := ds.Decl.(*ast.GenDecl)
	if !ok || gd.Tok != token.VAR || len(gd.Specs) != 1 {
		return "", nil
	}
	vs, ok := gd.Specs[0].(*ast.ValueSpec)
	if !ok || len(vs.Names) != 1 || len(vs.Values) != 0 {
		return "", nil
	}
	at, ok := vs.Type.(*ast.ArrayType)
	if !ok || at.Len != nil {
		return "", nil
	}
	return vs.Names[0].Name, at.Elt
}

// f1 is unigram multiset F1 between candidate and reference.
func f1(cand, ref []string) float64 {
	if len(cand) == 0 || len(ref) == 0 {
		return 0
	}
	counts := map[string]int{}
	for _, t := range ref {
		counts[t]++
	}
	overlap := 0
	for _, t := range cand {
		if counts[t] > 0 {
			counts[t]--
			overlap++
		}
	}
	p := float64(overlap) / float64(len(cand))
	r := float64(overlap) / float64(len(ref))
	if p+r == 0 {
		return 0
	}
	return 2 * p * r / (p + r)
}

func loadModel(projectRoot, modelPath string) (*seq2seq.Seq2Seq, error) {

	placeholder, err := tokenizer.NewTokenizer(mainvocab.NewVocabulary())
	if err != nil {
		return nil, err
	}
	if modelPath == "" {
		modelPath = chat.RealModelPath(projectRoot, chat.CodeIntentDomain)
	}
	model, err := seq2seq.Load(modelPath, placeholder)
	if err != nil {
		return nil, err
