func reportGate(name string, g *seq2seq.CopyGate) {
	if g == nil {
		fmt.Printf("=== %s: nil ===\n", name)
		return
	}
	bg := g.Bg.Data[0]
	g0 := 1.0 / (1.0 + math.Exp(float64(-bg)))
	var wnorm float64
	for _, w := range g.Wg.Data {
		wnorm += float64(w) * float64(w)
	}
	wnorm = math.Sqrt(wnorm)
	fmt.Printf("=== %s ===\n", name)
	fmt.Printf("Bg=%.4f (init -2.0) -> gate@zero-query=%.4f (init 0.1192)\n", bg, g0)
	fmt.Printf("||Wg||_2=%.6f (init 0.0), dim=%d\n", wnorm, g.HiddenDim)
	fmt.Printf("gate moved from init: %v\n", math.Abs(g0-0.1192) > 0.01 || wnorm > 1e-6)
}

// snippetCalls lists the callees by the names they are called with in the
// snippet. A callee is listed only if its bare name appears in the
// function's source, so every named call is visible in the [code] block.
func snippetCalls(p *analyze.Project, fn *analyze.Func) string {
	var names []string
	seen := map[string]bool{}
	for _, id := range fn.Calls {
		callee := p.FuncByID(id)
		if callee == nil || callee.Name == "" || seen[callee.Name] {
			continue
		}
		seen[callee.Name] = true
		if !strings.Contains(fn.Src, callee.Name) {
			continue
		}
		names = append(names, callee.Name)
		if len(names) >= 8 {
			break
		}
	}
	if len(names) == 0 {
		return "Calls in this code: none.\n"
	}
	return "Calls in this code: " + strings.Join(names, ", ") + ".\n"
}

// teachCard is the snippet-derivable answer card: signature, location,
// and the one-line purpose (doc first sentence when present, otherwise
// derived from the name). Deliberately no "Calls (N):"/"Called by (N):"
// project-graph lines — those facts are not in the [code] block.
func teachCard(fn *analyze.Func) string {
	return fmt.Sprintf("%s\n  %s:%d\n  %s\n", fn.Sig, fn.File, fn.Line, fn.Summary())
}

func disableRawMode(fd uintptr, oldState *syscall.Termios) {
	if oldState != nil {
		var reqSet uintptr
		if runtime.GOOS == "darwin" {
			reqSet = tiocseta
		} else {
			reqSet = tcsets
		}
		_, _, _ = syscall.Syscall(syscall.SYS_IOCTL, fd, reqSet, uintptr(unsafe.Pointer(oldState)))
	}
}

func enableRawMode(fd uintptr) (*syscall.Termios, error) {
	var oldState syscall.Termios
	var reqGet uintptr

	if runtime.GOOS == "darwin" {
		reqGet = tiocgeta
	} else {
		reqGet = tcgets
	}

	if _, _, err := syscall.Syscall(syscall.SYS_IOCTL, fd, reqGet, uintptr(unsafe.Pointer(&oldState))); err != 0 {
		return nil, err
	}

	newState := oldState
	newState.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	newState.Oflag &^= syscall.OPOST
	newState.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	newState.Cflag &^= syscall.CSIZE | syscall.PARENB
	newState.Cflag |= syscall.CS8

	var reqSet uintptr
	if runtime.GOOS == "darwin" {
		reqSet = tiocseta
	} else {
		reqSet = tcsets
	}

	if _, _, err := syscall.Syscall(syscall.SYS_IOCTL, fd, reqSet, uintptr(unsafe.Pointer(&newState))); err != 0 {
		return nil, err
	}
	return &oldState, nil
}

func fuzzyMatch(target, query string) (bool, int) {
	if query == "" {
		return true, 0
	}
	targetLower := strings.ToLower(target)
	queryLower := strings.ToLower(query)

	tIdx, score := 0, 0
	for qIdx := 0; qIdx < len(queryLower); qIdx++ {
		found := false
		for ; tIdx < len(targetLower); tIdx++ {
			if targetLower[tIdx] == queryLower[qIdx] {
				score += 10 - tIdx
				tIdx++
				found = true
				break
			}
		}
		if !found {
			return false, 0
		}
	}
	return true, score
}

func getTerminalSize(fd uintptr) (width, height int) {
	var ws winsize
	var req uintptr
	if runtime.GOOS == "darwin" {
		req = tiocgwinszDarwin
	} else {
		req = tiocgwinsz
	}

	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, fd, req, uintptr(unsafe.Pointer(&ws)))
	if err != 0 || ws.Row == 0 || ws.Col == 0 {
		return 80, 25
	}
	return int(ws.Col), int(ws.Row)
}

func parseChoice(line string) Choice {
	parts := strings.Fields(line)
	if len(parts) == 0 {
		return Choice{Raw: line}
	}
	cmd := parts[0]
	comment := ""
	if len(parts) > 1 {
		comment = strings.Join(parts[1:], " ")
	}
	return Choice{
		Command:	cmd,
		Comment:	comment,
		Raw:		line,
	}
}

func (p *picker) moveDown(rows, total int) {
	if p.sel%rows < rows-1 && p.sel+1 < total {
		p.sel++
	}
}

func (p *picker) moveLeft(rows int) {
	if p.sel-rows >= 0 {
		p.sel -= rows
	}
}

func (p *picker) moveRight(rows, total int) {
	if p.sel+rows < total {
		p.sel += rows
	}
}

func (p *picker) moveUp(rows int) {
	if p.sel%rows > 0 {
		p.sel--
	}
}

// processKeys consumes complete key events from the front of pending and
// returns the number of bytes consumed plus an action for the caller.
// Every byte of a burst is processed; a trailing partial escape sequence
// is left unconsumed so the next read can complete it.
