			switch pending[i+2] {
			case 'A':
				p.moveUp(rows)
			case 'B':
				p.moveDown(rows, total)
			case 'C':
				p.moveRight(rows, total)
			case 'D':
				p.moveLeft(rows)
			case 'M':

				skip = 6
			}
			if len(pending)-i < skip {

				return i, keyNone
			}
			i += skip

		default:
