// AnalyzeFailures computes the failure modes for a function.
func (fn *Func) AnalyzeFailures(p *Project) FailureMode {
	fm := FailureMode{}

	if strings.Contains(fn.Sig, "error") {
		fm.CanFail = true
	}

	for _, g := range fn.Guards {
		cond := strings.ToLower(g.Cond)
		if strings.Contains(cond, "err !=") {
			fm.ErrorChecks = append(fm.ErrorChecks, g.Cond)
		}
	}

	for _, callerID := range fn.Callers {
		if caller := p.byID[callerID]; caller != nil {
			for _, g := range caller.Guards {
				if strings.Contains(strings.ToLower(g.Cond), "err") {
					fm.HandledBy = append(fm.HandledBy, caller.Name)
					break
				}
			}
		}
	}

	fm.RetrySafe = len(fn.Writes) == 0 && !fn.MutatesAll

	for _, e := range fn.ExtCalls {
		if e == "panic" {
			fm.Panics = append(fm.Panics, "calls panic")
		}
	}

	return fm
}

// ContextualRole determines the function's role from the call graph.
func (fn *Func) ContextualRole() Role {
	callers := len(fn.Callers)
	callees := len(fn.Calls)

	if fn.IsMain || fn.IsInit {
		return RoleEntryPoint
	}
	if callers == 0 && callees == 0 {
		return RoleIsolated
	}
	if callers == 0 {
		return RoleEntryPoint
	}
	if callees == 0 {
		return RoleLeaf
	}

	if callees >= 3 && callers <= 2 {
		return RoleCoordinator
	}

	if callers >= 3 && callees <= 2 {
		return RoleWorker
	}

	if callers >= 3 && callees >= 3 {
		return RoleHub
	}

	return RoleWorker
}

// Control returns the control-flow summary for a function.
func (fn *Func) Control() ControlSummary {
	cs := ControlSummary{
		Branches:	len(fn.Guards),
		Loops:		len(fn.LoopCalls),
	}
	for _, g := range fn.Guards {
		cond := strings.ToLower(g.Cond)
		if strings.Contains(cond, "err !=") || strings.Contains(cond, "err ==") {
			cs.ErrorPaths = append(cs.ErrorPaths, g.Cond)
		}
	}

	for _, e := range fn.ExtCalls {
		if strings.Contains(e, "defer") {
			cs.HasDefer = true
			break
		}
	}
	return cs
}

// ControlPhrase renders the control flow as a plain sentence.
func (fn *Func) ControlPhrase() string {
	cs := fn.Control()
	var parts []string
	if cs.Branches > 0 {
		if cs.Branches == 1 {
			parts = append(parts, "1 branch")
		} else {
			parts = append(parts, fmt.Sprintf("%d branches", cs.Branches))
		}
	}
	if cs.Loops > 0 {
		if cs.Loops == 1 {
			parts = append(parts, "1 loop")
		} else {
			parts = append(parts, fmt.Sprintf("%d loops", cs.Loops))
		}
	}
	if len(cs.ErrorPaths) > 0 {
		parts = append(parts, fmt.Sprintf("handles errors (%s)", strings.Join(cs.ErrorPaths, ", ")))
	}
	if cs.HasDefer {
		parts = append(parts, "uses defer for cleanup")
	}
	if len(parts) == 0 {
		return "straight-line code, no branches or loops"
	}
	return strings.Join(parts, ", ")
}

// Detail renders the full readable card for a function.
func (fn *Func) Detail(p *Project) string {
	var b strings.Builder
	fmt.Fprintf(&b, "%s\n", fn.Sig)
