	type fl struct {
		rel	string
		lines	int
	}
	var files []fl
	for _, pkg := range p.Packages {
		for _, rel := range pkg.Files {
			data, err := os.ReadFile(filepath.Join(p.Root, rel))
			if err != nil {
				continue
			}
			files = append(files, fl{rel, countLines(data)})
		}
	}
	sort.Slice(files, func(i, j int) bool { return files[i].lines > files[j].lines })
	if len(files) > n {
		files = files[:n]
	}
	var b strings.Builder
	fmt.Fprintf(&b, "BIGGEST FILES (top %d)\n", len(files))
	max := 0
	for _, f := range files {
		if f.lines > max {
			max = f.lines
		}
	}
	for _, f := range files {
		fmt.Fprintf(&b, "  %-40s %s %d\n", p.LinkPath(f.rel), bars(f.lines, max, 24), f.lines)
	}
	return b.String()
