// Document renders full markdown documentation for the project: package
// overview, then every function and type with its signature and summary.
func (p *Project) Document() string {
	var b strings.Builder
	b.WriteString(fmt.Sprintf("# %s\n\n", p.Module))
	if p.Module == "" {
		b.WriteString("# Project\n\n")
	}
	b.WriteString(fmt.Sprintf("%d packages, %d files, %d lines\n\n", len(p.Packages), p.Files, p.Lines))

	for _, pkg := range p.Packages {
		b.WriteString(fmt.Sprintf("## Package %s\n\n", pkg.Name))
		if pkg.Doc != "" {
			b.WriteString(pkg.Doc + "\n\n")
		}
		b.WriteString(fmt.Sprintf("Directory: `%s` — %d functions, %d types\n\n",
			pkg.Dir, len(pkg.Funcs), len(pkg.Types)))

		if len(pkg.Types) > 0 {
			b.WriteString("### Types\n\n")
			for _, t := range pkg.Types {
				b.WriteString(t.Document(p))
				b.WriteString("\n")
			}
		}

		if len(pkg.Funcs) > 0 {
			b.WriteString("### Functions\n\n")
			fns := append([]*Func{}, pkg.Funcs...)
			sort.Slice(fns, func(i, j int) bool { return fns[i].Name < fns[j].Name })
			for _, fn := range fns {
				if fn.IsTest {
					continue
				}
				b.WriteString(fn.Document(p))
				b.WriteString("\n")
			}
		}
	}
	return b.String()
}

// EngineRoom renders the top functions as an ASCII bar chart.
func (p *Project) EngineRoom(n int) string {
	top := p.TopFuncs(n)
	if len(top) == 0 {
		return "no functions found\n"
	}
	max := 0
	for _, fn := range top {
		if len(fn.Callers) > max {
			max = len(fn.Callers)
		}
	}
	var b strings.Builder
	b.WriteString("ENGINE ROOM (most-called functions)\n")
	for _, fn := range top {
		bars := 0
		if max > 0 {
			bars = 1 + 19*len(fn.Callers)/max
		}
		fmt.Fprintf(&b, "%s %s (%d callers)\n", strings.Repeat("█", bars), fn.Display(), len(fn.Callers))
	}
	return b.String()
}

