// ExplainBeginner runs symbol through the xray engine and renders the
// beginner walkthrough. It reports ok=false when the symbol doesn't
// resolve to a function, letting the caller fall back to the reference
// answer.
func (p *Project) ExplainBeginner(symbol string) (string, bool) {
	fn, _, _, _ := p.resolve(symbol)
	if fn == nil {
		return "", false
	}
	src, err := os.ReadFile(filepath.Join(p.Root, fn.File))
	if err != nil {
		return "", false
	}
	ctx, cancel := context.WithTimeout(context.Background(), xrayTimeout)
	defer cancel()
	resp, err := xray.SynthesizeWithXRay(ctx, xray.XRayRequest{
		Query:		fmt.Sprintf("trace %q", fn.Name),
		ContextCode:	string(src),
	})
	if err != nil {
		return "", false
	}
	return renderXrayWalk(fn, resp), true
}

// FactsForExplain resolves name and builds the neural explainer input in
// the exact format the codeintent model was trained on:
// [file <file:line>], [code] source excerpt, [question] question.
// ok=false when the symbol doesn't resolve to a function.
func (p *Project) FactsForExplain(name, question string) (ExplainFacts, bool) {
	fn, _, _, _ := p.resolve(name)
	if fn == nil {
		return ExplainFacts{}, false
	}
	var b strings.Builder
	fmt.Fprintf(&b, "[file %s:%d]\n[code]\n%s\n[question] %s", fn.File, fn.Line, p.SourceOf(fn, 40), question)
	return ExplainFacts{
		Sig:		fn.Sig,
		FileLine:	fmt.Sprintf("%s:%d", p.LinkPath(fn.File), fn.Line),
		Summary:	fn.Summary(),
		Input:		b.String(),
	}, true
}

