// KeyTypes returns exported struct/interface types, interfaces with
// implementers first, then by method count.
func (p *Project) KeyTypes(n int) []*Type {
	var out []*Type
	for _, pkg := range p.Packages {
		for _, t := range pkg.Types {
			if t.Exported && (t.Kind == "struct" || t.Kind == "interface") {
				out = append(out, t)
			}
		}
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].ImplCount != out[j].ImplCount {
			return out[i].ImplCount > out[j].ImplCount
		}
		if len(out[i].Methods) != len(out[j].Methods) {
			return len(out[i].Methods) > len(out[j].Methods)
		}
		return out[i].Name < out[j].Name
	})
	if len(out) > n {
		out = out[:n]
	}
	return out
}

// LinkPath renders a project-relative file path as a terminal-clickable
// link. When the analyzed project isn't the working directory — a fresh
// clone in ./example, a repo in ~/elsewhere — the path is rewritten
// relative to the working directory, so file:line links click through
// to the file. When the project is the working directory, the path is
// unchanged.
func (p *Project) LinkPath(rel string) string {
	if p.Root == "" || rel == "" {
		return rel
	}
	cwd, err := os.Getwd()
	if err != nil {
		return rel
	}
	if r, err := filepath.Rel(cwd, filepath.Join(p.Root, rel)); err == nil && r != "" {
		return r
	}
	return rel
}

