			fmt.Fprintf(&b, "  ... and %d more\n", len(ids)-12)
			break
		}
		if f := p.byID[id]; f != nil {
			fmt.Fprintf(&b, "  - %s  (%s:%d)\n", f.Display(), p.LinkPath(f.File), f.Line)
		} else {
			fmt.Fprintf(&b, "  - %s\n", shortID(id))
		}
	}
	return b.String(), true
}

// answerWhereDefined handles "where is X defined".
func (p *Project) answerWhereDefined(name string) (string, bool) {
	fn, cands, typ, pkg := p.resolve(name)
	switch {
	case fn != nil:
		return fmt.Sprintf("%s is defined at %s:%d\n", fn.Display(), p.LinkPath(fn.File), fn.Line), true
	case typ != nil:
		return fmt.Sprintf("type %s.%s is defined at %s:%d\n", typ.Pkg, typ.Name, p.LinkPath(typ.File), typ.Line), true
	case pkg != nil:
		dir := pkg.Dir
		if dir == "" {
			dir = "."
		}
		return fmt.Sprintf("package %s lives in %s/\n", pkg.Name, dir), true
	case len(cands) > 0:
		return p.ambiguous(name, cands), true
	}
	return "", false
}

// answerWhoSets handles "where is X set" / "who sets X": the write
// index — every function that assigns the value.
func (p *Project) answerWhoSets(name string) (string, bool) {
	keys := p.resolveField(name)
	if len(keys) == 0 {
		return "", false
	}
	seen := map[string]bool{}
	var ids []string
	for _, k := range keys {
		for _, id := range p.FieldWriters(k) {
			if !seen[id] {
				seen[id] = true
				ids = append(ids, id)
			}
		}
	}
	sort.Strings(ids)
	if len(ids) == 0 {
		return "", false
	}
	var b strings.Builder
	fmt.Fprintf(&b, "`%s` is set by %d function(s):\n", name, len(ids))
	for i, id := range ids {
		if i >= 12 {
			fmt.Fprintf(&b, "  ... and %d more\n", len(ids)-12)
			break
		}
		if f := p.byID[id]; f != nil {
			fmt.Fprintf(&b, "  - %s  (%s:%d)\n", f.Display(), p.LinkPath(f.File), f.Line)
		} else {
			fmt.Fprintf(&b, "  - %s\n", shortID(id))
		}
	}
	return b.String(), true
}

// answerWhyCalls handles "why does X call Y": the callee's purpose in
// infinitive form, plus the guard the call sits inside, if any.
func (p *Project) answerWhyCalls(callerName, calleeName string) (string, bool) {
	caller, _, _, _ := p.resolve(callerName)
	callee, _, _, _ := p.resolve(calleeName)
	if caller == nil || callee == nil {
		return "", false
	}
	callsIt := false
	for _, id := range caller.Calls {
		if id == callee.ID {
			callsIt = true
			break
		}
	}
	if !callsIt {
		return fmt.Sprintf("%s doesn't call %s.", caller.Display(), callee.Display()), true
	}
	vp := verbPhrase(callee.Name, false)
	if strings.HasPrefix(vp, "handles ") {

		return fmt.Sprintf("%s calls %s. %s", caller.Display(), callee.Display(), callee.Intent()), true
	}
	var b strings.Builder
	fmt.Fprintf(&b, "%s calls %s to %s.", caller.Display(), callee.Display(), vp)
	for _, g := range caller.Guards {
		for _, id := range g.Calls {
			if id == callee.ID {
				fmt.Fprintf(&b, " (inside the `%s` check)", g.Cond)
				break
			}
		}
	}
	return b.String(), true
}

