// buildFieldReaders computes the value-flow index by fixpoint over the
// call graph. Called from BuildGraph after the per-function passes.
func (p *Project) buildFieldReaders() {
	direct := map[string]map[string]bool{}
	add := func(field, id string) bool {
		m := direct[field]
		if m == nil {
			m = map[string]bool{}
			direct[field] = m
		}
		if m[id] {
			return false
		}
		m[id] = true
		return true
	}
	for _, fn := range p.byID {
		for _, r := range fn.Reads {
			add(r, fn.ID)
		}
	}

	for changed := true; changed; {
		changed = false
		for _, fn := range p.byID {
			for _, ca := range fn.CallArgs {
				if ca.Target == "" {
					continue
				}
				g := p.byID[ca.Target]
				if g == nil {
					continue
				}
				for _, a := range ca.Args {
					t := valueTypeOf(fn, a)
					if t == "" || !receivesType(g, t) {
						continue
					}
					prefix := t + "."
					for field, readers := range direct {
						if !strings.HasPrefix(field, prefix) || !readers[g.ID] {
							continue
						}
						if add(field, fn.ID) {
							changed = true
						}
					}
				}
			}
		}
	}
	p.fieldReaders = map[string][]string{}
	for f, m := range direct {
		p.fieldReaders[f] = sortedKeys(m)
	}
}

// buildFieldWriters computes the write index: which functions set which
// values. Direct only — unlike reads, a write is meaningful exactly
// where it happens.
func (p *Project) buildFieldWriters() {
	p.fieldWriters = map[string][]string{}
	byField := map[string]map[string]bool{}
	for _, fn := range p.byID {
		for _, w := range fn.Writes {
			m := byField[w]
			if m == nil {
				m = map[string]bool{}
				byField[w] = m
			}
			m[fn.ID] = true
		}
	}
	for f, m := range byField {
		p.fieldWriters[f] = sortedKeys(m)
	}
}

func (p *Project) buildNewCodePlan(c IssueConcepts) *newCodePlan {
	paths := missingPaths(p, c)
	if len(paths) == 0 {
		return nil
	}
	pkg := p.targetPackage(c)
	if pkg == nil {
		return nil
	}
	np := &newCodePlan{newPaths: paths, target: pkg}
	np.targets = p.packageTargets(pkg, c)
	np.patterns = p.testPatterns(pkg, c)

	if wantsReplace(c) {
		if files := existingPaths(p, c); len(files) > 0 {
			if calls := namedCalls(c); len(calls) > 0 {
				np.replaceCalls = calls
				np.replace = p.replaceSites(files, calls)
			}
		}
	}

	if len(np.newPaths) > 0 {
		np.follow = p.siblingCommands(np.newPaths[0])
	}

	np.reuse = p.reuseFuncs(c)

	np.also = p.alsoFiles(c, np)
	return np
}

func (p *Project) buildTypeMethodPlan(c IssueConcepts) *typeMethodPlan {
	typ := p.targetType(c)
	if typ == nil {
		return nil
	}
	name := methodName(c)
	if name == "" {
		return nil
	}
	methods := p.typeMethods(typ)
	for _, m := range methods {
		if strings.EqualFold(m.Name, name) {
			return nil
		}
	}
	tp := &typeMethodPlan{typ: typ, methodName: name}
	for _, pkg := range p.Packages {
		for _, t := range pkg.Types {
			if t == typ {
				tp.pkg = pkg
			}
		}
	}
	tp.receiver = commonReceiver(methods)
	tp.siblings = rankSiblings(methods, c)
	tp.wantsOpts = strings.Contains(strings.ToLower(c.Title+" "+c.Body), "option")
	if tp.pkg != nil {
		tp.optUser = map[string]*Func{}
		for _, t := range tp.pkg.Types {
			if t.Kind == "struct" && strings.HasSuffix(t.Name, "Option") {
				tp.optTypes = append(tp.optTypes, t)
				if u := optionUser(tp.pkg, t.Name); u != nil {
					tp.optUser[t.Name] = u
				}
			}
		}
		sort.Slice(tp.optTypes, func(i, j int) bool { return tp.optTypes[i].Name < tp.optTypes[j].Name })
	}
	return tp
}

// callRoots returns exported functions nothing calls, by importance —
// the API surface a library is used through.
func (p *Project) callRoots(n int) []*Func {
	var roots []*Func
	for _, fn := range p.byID {
		if fn.Exported && !fn.IsTest && !fn.IsInit && len(fn.Callers) == 0 {
			roots = append(roots, fn)
		}
	}
	sort.Slice(roots, func(i, j int) bool {
		if roots[i].Score != roots[j].Score {
			return roots[i].Score > roots[j].Score
		}
		return roots[i].ID < roots[j].ID
	})
	if len(roots) > n {
		roots = roots[:n]
	}
	return roots
}

// codeRefs finds functions the issue names through `backticked` words:
// every word of the code word must appear in the function name.
// Single-word code words are too generic to be references.
func (p *Project) codeRefs(c IssueConcepts) map[string][]*Func {
	out := map[string][]*Func{}
	for _, w := range c.CodeWords {
		toks := wordTokens(w)
		if len(toks) < 2 {
			continue
		}
		for _, pkg := range p.Packages {
			for _, fn := range pkg.Funcs {
				if fn.IsTest {
					continue
				}
				nameSet := map[string]bool{}
				for _, t := range tokenizeName(fn.Name) {
					nameSet[t] = true
				}
				all := true
				for _, t := range toks {
					if !nameSet[t] {
						all = false
						break
					}
				}
				if all {
					out[w] = append(out[w], fn)
				}
			}
		}
	}
	return out
}

