// finalize sorts everything for stable output and drops the ASTs.
func (p *Project) finalize() {
	sort.Slice(p.Packages, func(i, j int) bool { return p.Packages[i].Dir < p.Packages[j].Dir })
	for _, pkg := range p.Packages {
		sort.Strings(pkg.Files)
		sort.Strings(pkg.Imports)
		sort.Slice(pkg.Funcs, func(i, j int) bool { return pkg.Funcs[i].ID < pkg.Funcs[j].ID })
		sort.Slice(pkg.Types, func(i, j int) bool { return pkg.Types[i].Name < pkg.Types[j].Name })
		for _, fn := range pkg.Funcs {
			fn.decl = nil
		}
	}
}

// findConfigFlow finds the flow for a new-flag issue via the config
// type itself: the orchestrator among the config's field readers. A new
// flag becomes a config field, so the flow is where config is consumed —
// no keyword luck needed. (E.g. "--force" matches no function name, but
// the config's readers lead to the flow.)
func (p *Project) findConfigFlow(t *Type, pkg *Package) *Func {
	seen := map[string]*Func{}
	var walk func(fn *Func)
	walk = func(fn *Func) {
		if fn == nil || seen[fn.ID] != nil {
			return
		}
		seen[fn.ID] = fn
		for _, id := range fn.Callers {
			walk(p.byID[id])
		}
	}
	for _, f := range t.Fields {
		key := pkg.Name + "." + t.Name + "." + f
		for _, id := range p.FieldReaders(key) {
			walk(p.byID[id])
		}
	}
	var best *Func
	for _, fn := range seen {
		if fn.IsMain || fn.IsTest || fn.IsInit || isConstructor(fn.Name) {
			continue
		}
		if best == nil || len(fn.Calls) > len(best.Calls) {
			best = fn
		}
	}
	return best
}

// findConfigType locates "type Config struct", preferring config packages.
func (p *Project) findConfigType() (*Type, *Package) {
	var best *Type
	var bestPkg *Package
	bestScore := -1
	for _, pkg := range p.Packages {
		for _, t := range pkg.Types {
			if t.Kind != "struct" || t.Name != "Config" {
				continue
			}
			score := 0
			if strings.Contains(strings.ToLower(pkg.Dir), "config") {
				score += 2
			}
			if strings.Contains(strings.ToLower(pkg.Name), "config") {
				score++
			}
			if score > bestScore {
				bestScore, best, bestPkg = score, t, pkg
			}
		}
	}
	return best, bestPkg
}

// findFlow picks the orchestrating function behind candidate funcs: walk
// each candidate's callers up toward main and take the non-main function
// with the most callees. Constructors never orchestrate a feature.
func (p *Project) findFlow(cands []*Func) *Func {
	seen := map[string]*Func{}
	var walk func(fn *Func)
	walk = func(fn *Func) {
		if fn == nil || seen[fn.ID] != nil {
			return
		}
		seen[fn.ID] = fn
		for _, id := range fn.Callers {
			walk(p.byID[id])
		}
	}
	for _, c := range cands {
		walk(c)
	}
	var best *Func
	for _, fn := range seen {
		if fn.IsMain || fn.IsTest || fn.IsInit || isConstructor(fn.Name) {
			continue
		}
		if best == nil || len(fn.Calls) > len(best.Calls) {
			best = fn
		}
	}
	return best
}

// findFunc looks up a plain function by name in pkg.
func (p *Project) findFunc(pkg *Package, recv, name string) *Func {
	for _, fn := range pkg.Funcs {
		if fn.Receiver == recv && fn.Name == name {
			return fn
		}
	}
	return nil
}

// findMethod looks up a method by name in pkg, preferring an exact
// receiver-type match is impossible without type info, so the first
// same-package method with that name wins. Method names are usually
// unique enough within a package for mapping purposes.
func (p *Project) findMethod(pkg *Package, name string) *Func {
	for _, m := range p.byMethod[name] {
		if m.pkg == pkg {
			return m
		}
	}
	return nil
}

// findPackage finds a package by name or directory, case-insensitively.
func (p *Project) findPackage(name string) *Package {
	lower := strings.ToLower(name)
	for _, pk := range p.Packages {
		if strings.EqualFold(pk.Name, name) || strings.EqualFold(pk.Dir, name) ||
			strings.EqualFold(shortDir(pk.Dir), lower) {
			return pk
		}
	}
	return nil
}

// flowFlagSites returns the flag-like guard sites in the flow function
// itself, deduplicated by condition. These are the local pattern a new
// flag should imitate: same shape, same neighborhood.
func (p *Project) flowFlagSites(flow *Func) []flagSite {
	seen := map[string]bool{}
	var out []flagSite
	for _, g := range flow.Guards {
		if !g.FlagLike || seen[g.Cond] {
			continue
		}
		seen[g.Cond] = true
		out = append(out, flagSite{Cond: g.Cond, File: flow.File, Line: g.Line})
		if len(out) >= 3 {
			break
		}
	}
	return out
}

// flowMutations lists the functions reachable from flow that directly
// mutate the filesystem, with the external calls they mutate through.
// Capped so the plan stays readable.
func (p *Project) flowMutations(flow *Func) []mutation {
	seen := map[string]bool{}
	var out []mutation
	var visit func(fn *Func)
	visit = func(fn *Func) {
		if fn == nil || seen[fn.ID] {
			return
		}
		seen[fn.ID] = true
		if fn.Mutates {
			var via []string
			for _, e := range fn.ExtCalls {
				if hasEffect(callEffects[e], fxWrite) {
					via = append(via, e)
				}
			}
			sort.Strings(via)
			out = append(out, mutation{FuncName: fn.Name, Via: via, File: fn.File, Line: fn.Line})
		}
		for _, id := range fn.Calls {
			visit(p.byID[id])
		}
	}
	for _, id := range flow.Calls {
		visit(p.byID[id])
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].FuncName != out[j].FuncName {
			return out[i].FuncName < out[j].FuncName
		}
		return out[i].File < out[j].File
	})
	if len(out) > 4 {
		out = out[:4]
	}
	return out
}

// funcForObject maps a type-checker function object back to the model.
func (p *Project) funcForObject(obj *types.Func) *Func {
	rel := strings.TrimPrefix(strings.TrimPrefix(obj.Pkg().Path(), p.Module), "/")
	sig, ok := obj.Type().(*types.Signature)
	if !ok {
		return nil
	}
	recv := ""
	if r := sig.Recv(); r != nil {
		recv = namedTypeName(r.Type())
	}
	return p.byID[funcID(rel, recv, obj.Name())]
}

// funcSeeds ranks non-test functions by overlap with keywords: name hits
// count most, then doc, then package.
func (p *Project) funcSeeds(keywords []string, n int) []funcSeed {
	var seeds []funcSeed
	for _, pkg := range p.Packages {
		pkgHay := strings.ToLower(pkg.Name + " " + pkg.Dir)
		for _, fn := range pkg.Funcs {
			if fn.IsTest {
				continue
			}
			nameToks := tokenizeName(fn.Name)
			docHay := strings.ToLower(fn.Doc)
			score := 0
			for _, kw := range keywords {
				for _, t := range nameToks {
					if t == kw {
						score += 3
						break
					}
				}
				if strings.Contains(docHay, kw) {
					score += 2
				}
				if strings.Contains(pkgHay, kw) {
					score++
				}
			}
			if score > 0 {
				seeds = append(seeds, funcSeed{fn, score})
			}
		}
	}
	sort.Slice(seeds, func(i, j int) bool {
		if seeds[i].score != seeds[j].score {
			return seeds[i].score > seeds[j].score
		}
		return seeds[i].fn.Name < seeds[j].fn.Name
	})
	if len(seeds) > n {
		seeds = seeds[:n]
	}
	return seeds
}

// importTarget returns the project package for an import path, or nil for
// external dependencies. Matching is by module-relative directory: an
// import of <module>/a/b resolves to the package in dir a/b.
func (p *Project) importTarget(imp string) *Package {
	if p.Module != "" {
		if rest, ok := strings.CutPrefix(imp, p.Module+"/"); ok {
			if pkg, ok := p.byPkgDir[rest]; ok {
				return pkg
			}
		}
		if imp == p.Module {
			if pkg, ok := p.byPkgDir[""]; ok {
				return pkg
			}
		}
	}

	for _, pkg := range p.Packages {
		dir := pkg.Dir
		if dir == "" {
			continue
		}
		if strings.HasSuffix(imp, "/"+dir) || imp == dir {
			return pkg
		}
	}
	return nil
}

// knowsSymbol reports whether name resolves to anything in the project.
func (p *Project) knowsSymbol(name string) bool {
	fn, _, typ, pkg := p.resolve(name)
	return fn != nil || typ != nil || pkg != nil
}

// lineOf returns the 1-based line of a node using the FileSet kept from
// the scan phase (one shared FileSet per analyzed project).
func (p *Project) lineOf(fn *Func, n ast.Node) int {
	if fn.fset == nil {
		return 0
	}
	if pos := fn.fset.Position(n.Pos()); pos.IsValid() {
		return pos.Line
	}
	return 0
}

// linkInternal fills each package's Internal list from its Imports.
func (p *Project) linkInternal() {
	for _, pkg := range p.Packages {
		var internal []string
		for _, imp := range pkg.Imports {
			if target := p.importTarget(imp); target != nil {
				dir := target.Dir
				if dir != pkg.Dir && !contains(internal, dir) {
					internal = append(internal, dir)
				}
			}
		}
		sort.Strings(internal)
		pkg.Internal = internal
	}
}

// methodsOf returns the method names declared on a type.
func (p *Project) methodsOf(t *Type) []string {
	var out []string
	for _, pkg := range p.Packages {
		for _, fn := range pkg.Funcs {
			if fn.Receiver == t.Name {
				out = append(out, fn.Name)
			}
		}
	}
	return out
}

// packageForFile returns the package containing the project-relative file.
func (p *Project) packageForFile(rel string) *Package {
	dir := path.Dir(rel)
	if dir == "." {
		dir = ""
	}
	best := (*Package)(nil)
	for _, pkg := range p.Packages {
		if pkg.Dir == dir || strings.HasPrefix(dir, pkg.Dir+"/") {
			if best == nil || len(pkg.Dir) > len(best.Dir) {
				best = pkg
			}
		}
	}
	return best
}

// packageTargets ranks the package's exported functions by keyword
// overlap with the issue's own vocabulary (title + body): the API
// surface the new code works against. Ties break toward hot paths
// (more callers), then name.
func (p *Project) packageTargets(pkg *Package, c IssueConcepts) []*Func {
	kw := map[string]bool{}
	for _, s := range wordTokens(c.Title) {
		kw[s] = true
	}
	for _, s := range wordTokens(c.Body) {
		kw[s] = true
	}
	for _, m := range c.Mechanisms {
		kw[stem(m)] = true
	}
	type scored struct {
		fn	*Func
		score	int
	}
	var ss []scored
	for _, fn := range pkg.Funcs {
		if fn.IsTest || !fn.Exported {
			continue
		}
		score := 0
		for _, t := range tokenizeName(fn.Name) {
			if wordHit(t, kw) {
				score += 2
			}
		}
		ss = append(ss, scored{fn, score})
	}
	sort.Slice(ss, func(i, j int) bool {
		if ss[i].score != ss[j].score {
			return ss[i].score > ss[j].score
		}
		if len(ss[i].fn.Callers) != len(ss[j].fn.Callers) {
			return len(ss[i].fn.Callers) > len(ss[j].fn.Callers)
		}
		return ss[i].fn.Name < ss[j].fn.Name
	})
	var out []*Func
	for i, s := range ss {
		if i >= 5 {
			break
		}
		out = append(out, s.fn)
	}
	return out
}

func (p *Project) pkgFor(dir, pkgName string) *Package {
	if pkg, ok := p.byPkgDir[dir]; ok {
		return pkg
	}
	pkg := &Package{Name: pkgName, Dir: dir}
	p.byPkgDir[dir] = pkg
	p.Packages = append(p.Packages, pkg)
	return pkg
}

// projectOneLiner finds a human-written one-line description: the root
// package doc first, then the first main package's doc.
func (p *Project) projectOneLiner() string {
	if pkg := p.byPkgDir[""]; pkg != nil {
		if s := firstSentence(pkg.Doc); s != "" {
			return s
		}
	}
	for _, pkg := range p.Packages {
		if pkg.HasMain {
			if s := firstSentence(pkg.Doc); s != "" {
				return s
			}
		}
	}
	return ""
}

// propagateEffects fills EffectsAll (transitive effect categories) by
// fixpoint over the call graph, then derives Mutates/MutatesAll from the
// fs-write category.
func (p *Project) propagateEffects() {
	for _, fn := range p.byID {
		set := map[string]bool{}
		for _, e := range fn.ExtCalls {
			for _, c := range callEffects[e] {
				set[c] = true
			}
		}
		fn.Effects = sortedKeys(set)
	}
	for changed := true; changed; {
		changed = false
		for _, fn := range p.byID {
			set := map[string]bool{}
			for _, c := range fn.EffectsAll {
				set[c] = true
			}
			for _, c := range fn.Effects {
				if !set[c] {
					set[c] = true
					changed = true
				}
			}
			for _, id := range fn.Calls {
				if g := p.byID[id]; g != nil {
					for _, c := range g.EffectsAll {
						if !set[c] {
							set[c] = true
							changed = true
						}
					}
				}
			}
			fn.EffectsAll = sortedKeys(set)
		}
	}
	for _, fn := range p.byID {
		fn.Mutates = hasEffect(fn.Effects, fxWrite)
		fn.MutatesAll = hasEffect(fn.EffectsAll, fxWrite)
	}
}

// readingChain returns short package names in dependency-first order.
func (p *Project) readingChain(n int) []string {
	var out []string
	for _, dir := range p.readingOrderDirs() {
		if dir == "" {
			out = append(out, "main")
			continue
		}
		short := dir
		if i := strings.LastIndex(dir, "/"); i >= 0 {
			short = dir[i+1:]
		}
		out = append(out, short)
		if len(out) >= n {
			break
		}
	}
	return out
}

// readingOrder is the display form of readingOrderDirs ("" -> ". (root)").
func (p *Project) readingOrder() []string {
	out := p.readingOrderDirs()
	for i, d := range out {
		if d == "" {
			out[i] = ". (root)"
		}
	}
	return out
}

// readingOrderDirs returns package dirs sorted so dependencies come before the
// packages that import them (a topological-ish order by internal imports).
// "" means the root directory.
func (p *Project) readingOrderDirs() []string {
	depth := map[string]int{}
	var visit func(dir string, seen map[string]bool) int
	visit = func(dir string, seen map[string]bool) int {
		if d, ok := depth[dir]; ok {
			return d
		}
		if seen[dir] {
			return 0
		}
		seen[dir] = true
		pkg := p.byPkgDir[dir]
		max := 0
		if pkg != nil {
			for _, imp := range pkg.Internal {
				if d := visit(imp, seen); d+1 > max {
					max = d + 1
				}
			}
		}
		delete(seen, dir)
		depth[dir] = max
		return max
	}
	dirs := make([]string, 0, len(p.Packages))
	for _, pkg := range p.Packages {
		dirs = append(dirs, pkg.Dir)
		visit(pkg.Dir, map[string]bool{})
	}
	sort.Slice(dirs, func(i, j int) bool {
		if depth[dirs[i]] != depth[dirs[j]] {
			return depth[dirs[i]] < depth[dirs[j]]
		}
		return dirs[i] < dirs[j]
	})
	out := make([]string, len(dirs))
	copy(out, dirs)
	return out
}

func (p *Project) refinePackage(pkg *packages.Package) {
	info := pkg.TypesInfo
	if info == nil {
		return
	}
	rel := strings.TrimPrefix(strings.TrimPrefix(pkg.PkgPath, p.Module), "/")
	for _, file := range pkg.Syntax {
		for _, decl := range file.Decls {
			fd, ok := decl.(*ast.FuncDecl)
			if !ok || fd.Body == nil {
				continue
			}
			fn := p.byID[funcID(rel, declRecv(fd), fd.Name.Name)]
			if fn == nil {
				continue
			}
			ast.Inspect(fd.Body, func(n ast.Node) bool {
				call, ok := n.(*ast.CallExpr)
				if !ok {
					return true
				}
				if target := p.typedTarget(info, call); target != nil && target != fn {
					p.addEdge(fn, target)
				}
				return true
			})
		}
	}
}

// refineTypes loads the project with type info and adds the call edges
// the heuristics missed or got wrong. It runs inside BuildGraph before
// effect propagation, so refined edges carry effects.
func (p *Project) refineTypes() {
	if p.Module == "" {
		return
	}
	cfg := &packages.Config{
		Mode:	packages.NeedName | packages.NeedTypes | packages.NeedSyntax | packages.NeedTypesInfo,
		Dir:	p.Root,
	}
	pkgs, err := packages.Load(cfg, "./...")
	if err != nil {
		return
	}
	for _, pkg := range pkgs {
		if len(pkg.Errors) > 0 {
			return
		}
	}
	p.Typed = true
	for _, pkg := range pkgs {
		p.refinePackage(pkg)
	}
}

// replaceSites finds the non-test functions in the named files (or
// directories) that call the named external calls: the modification
// sites for a replacement.
func (p *Project) replaceSites(files []string, calls []string) []replaceSite {
	want := map[string]bool{}
	for _, c := range calls {
		want[c] = true
	}
	matchFile := func(rel string) bool {
		for _, f := range files {
			if rel == f || strings.HasPrefix(rel, f+"/") {
				return true
			}
		}
		return false
	}
	var out []replaceSite
	for _, fn := range p.byID {
		if fn.IsTest || !matchFile(fn.File) {
			continue
		}
		var via []string
		for _, e := range fn.ExtCalls {
			if want[e] {
				via = append(via, e)
			}
		}
		if len(via) > 0 {
			out = append(out, replaceSite{fn: fn, via: via})
		}
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].fn.File != out[j].fn.File {
			return out[i].fn.File < out[j].fn.File
		}
		return out[i].fn.Line < out[j].fn.Line
	})
	if len(out) > 6 {
		out = out[:6]
	}
	return out
}

