// resolveCall maps a call expression to a project function, or nil when
// it targets an external package or can't be resolved. Shared by the
// call-graph pass and the effect/guard collection so both see the same
// edges.
func (p *Project) resolveCall(pkg *Package, varPkg map[string]string, paramPkgs map[string]*Package, fn *Func, call *ast.CallExpr) *Func {
	var target *Func
	switch fun := call.Fun.(type) {
	case *ast.Ident:

		target = p.findFunc(pkg, "", fun.Name)
	case *ast.SelectorExpr:

		if id, ok := fun.X.(*ast.Ident); ok {
			target = p.findMethod(pkg, fun.Sel.Name)
			if target == nil {
				if alias, ok := varPkg[id.Name]; ok {
					if q, ok := pkg.aliasCache[alias]; ok {
						target = p.findMethod(q, fun.Sel.Name)
					}
				} else if q, ok := paramPkgs[id.Name]; ok {
					target = p.findMethod(q, fun.Sel.Name)
				} else if q, ok := pkg.aliasCache[id.Name]; ok {
					target = p.findFunc(q, "", fun.Sel.Name)
				}
			}
		}
	}
	if target == fn {
		return nil
	}
	return target
}

// resolveField maps a field name to "pkg.Type.Field" keys across every
// struct type in the project. A "--flag" prefix is stripped so "what
// reads --verbose" works too.
func (p *Project) resolveField(name string) []string {
	name = strings.Trim(name, "`\"' ")
	name = strings.TrimPrefix(name, "--")
	var keys []string
	for _, pkg := range p.Packages {
		for _, t := range pkg.Types {
			if t.Kind != "struct" {
				continue
			}
			for _, f := range t.Fields {
				if strings.EqualFold(f, name) {
					keys = append(keys, pkg.Name+"."+t.Name+"."+f)
				}
			}
		}
	}
	sort.Strings(keys)
	return keys
}

// reuseFuncs resolves "reuse X()" references: identifiers the issue
// says to reuse, resolved against the index.
func (p *Project) reuseFuncs(c IssueConcepts) []*Func {
	if !strings.Contains(strings.ToLower(c.Title+"\n"+c.Body), "reus") {
		return nil
	}
	var out []*Func
	seen := map[string]bool{}
	for _, m := range identParenRe.FindAllStringSubmatch(c.Title+"\n"+c.Body, -1) {
		name := m[1]
		if seen[name] {
			continue
		}
		seen[name] = true
		if fn, _, _, _ := p.resolve(name); fn != nil {
			out = append(out, fn)
		}
	}
	return out
}

