// siteMatchesTitle reports whether the mechanism site is what the issue
// title is about: the title names a mechanism word and that mechanism
// lives in the site's package. Otherwise a single anchor misleads —
// "Add Deletion Report Export" anchored on the file manager because the
// issue says "files" — and the multi-file plan takes over.
func (p *Project) siteMatchesTitle(c IssueConcepts, site *MechanismSite) bool {
	if site == nil {
		return false
	}
	words := map[string]bool{}
	for _, w := range strings.FieldsFunc(strings.ToLower(c.Title),
		func(r rune) bool { return r < 'a' || r > 'z' }) {
		words[w] = true
		words[singular(w)] = true
	}
	for _, m := range mechanismTable {
		if words[m] {
			if s := p.FindMechanism(m); s != nil && s.Pkg == site.Pkg {
				return true
			}
		}
	}
	return false
}

// structFields returns a struct's own fields plus one level of embedded
// struct fields (resource.ResourceConfig inlines into source.Config).
func (p *Project) structFields(t *Type) []string {
	out := append([]string{}, t.Fields...)
	byName := map[string]*Type{}
	for _, pkg := range p.Packages {
		for _, ot := range pkg.Types {
			if ot.Kind == "struct" {
				byName[ot.Name] = ot
			}
		}
	}
	for _, f := range t.Fields {
		if emb, ok := byName[f]; ok && emb != t {
			out = append(out, emb.Fields...)
		}
	}
	return out
}

// targetPackage resolves the module the new code is about. The
// new-code path's last segment names it: in
// internal/tests/benchmark/filemanager/ the module is "filemanager".
// Exact package-name match wins over partial ("filemanager" beats
// "filemanager_test").
func (p *Project) targetPackage(c IssueConcepts) *Package {
	norm := func(s string) string {
		var b strings.Builder
		for _, r := range strings.ToLower(s) {
			if r >= 'a' && r <= 'z' || r >= '0' && r <= '9' {
				b.WriteRune(r)
			}
		}
		return b.String()
	}
	for _, path := range missingPaths(p, c) {
		segs := strings.Split(strings.TrimSuffix(path, "/"), "/")
		last := segs[len(segs)-1]

		if strings.HasSuffix(last, ".go") && len(segs) >= 2 {
			last = segs[len(segs)-2]
		}
		want := norm(last)
		var partial *Package
		for _, pkg := range p.Packages {
			name := norm(pkg.Name)
			if name == want {
				return pkg
			}
			if partial == nil && strings.Contains(name, want) {
				partial = pkg
			}
		}
		if partial != nil {
			return partial
		}
	}
	return nil
}

// targetType resolves the issue's nouns to a struct type: the type the
// new method belongs to. Candidates rank by method count — the type the
// issue is about is usually the one with the rich API.
func (p *Project) targetType(c IssueConcepts) *Type {
	words := map[string]bool{}
	for _, w := range strings.FieldsFunc(strings.ToLower(c.Title),
		func(r rune) bool { return r < 'a' || r > 'z' }) {
		words[w] = true
		words[stem(w)] = true
	}
	var best *Type
	bestN := -1
	for _, pkg := range p.Packages {
		for _, t := range pkg.Types {
			if t.Kind != "struct" {
				continue
			}
			if !words[strings.ToLower(t.Name)] {
				continue
			}
			if n := len(p.typeMethods(t)); n > bestN {
				best, bestN = t, n
			}
		}
	}
	return best
}

// testPatterns finds existing test files to imitate: same package
// first, files with benchmarks preferred. Purely structural — it works
// for any kind of new test code.
func (p *Project) testPatterns(pkg *Package, c IssueConcepts) []string {
	type scored struct {
		rel	string
		score	int
	}

	named := map[string]bool{}
	for _, w := range c.CodeWords {
		w = strings.Trim(w, "`\"' ")
		if strings.HasSuffix(w, "_test.go") {
			named[strings.TrimSuffix(w, "/")] = true
		}
	}
	var ss []scored
	seen := map[string]bool{}
	for _, q := range p.Packages {
		for _, f := range q.Files {
			if !strings.HasSuffix(f, "_test.go") || seen[f] {
				continue
			}
			seen[f] = true
			score := 0
			if q == pkg {
				score += 2
			}
			if hasBenchmark(filepath.Join(p.Root, f)) {
				score += 3
			}
			if named[f] {
				score += 5
			}
			ss = append(ss, scored{f, score})
		}
	}
	sort.Slice(ss, func(i, j int) bool {
		if ss[i].score != ss[j].score {
			return ss[i].score > ss[j].score
		}
		return ss[i].rel < ss[j].rel
	})
	var out []string
	for i, s := range ss {
		if i >= 3 {
			break
		}
		out = append(out, s.rel)
	}
	return out
}

// topCallees resolves fn's callees to *Func, deduplicated in call-site
// order, skipping tests and init functions. The limit caps breadth.
func (p *Project) topCallees(fn *Func, limit int) []*Func {
	var out []*Func
	seen := map[string]bool{}
	for _, id := range fn.Calls {
		if seen[id] {
			continue
		}
		seen[id] = true
		c, ok := p.byID[id]
		if !ok || c.IsTest || c.IsInit {
			continue
		}
		out = append(out, c)
		if len(out) >= limit {
			break
		}
	}
	return out
}

// typeMethods returns the *Func methods declared on a type.
func (p *Project) typeMethods(t *Type) []*Func {
	var out []*Func
	for _, pkg := range p.Packages {
		for _, fn := range pkg.Funcs {
			if fn.IsTest {
				continue
			}
			if strings.TrimPrefix(fn.Receiver, "*") == t.Name {
				out = append(out, fn)
			}
		}
	}
	return out
}

// typedTarget resolves a call through the type checker's method sets.
// Selections covers x.Method() for concrete types, interfaces, and
// embedded fields — the cases the name heuristics guess at.
func (p *Project) typedTarget(info *types.Info, call *ast.CallExpr) *Func {
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return nil
	}
	s, ok := info.Selections[sel]
	if !ok {
		return nil
	}
	obj, ok := s.Obj().(*types.Func)
	if !ok || obj.Pkg() == nil {
		return nil
	}
	return p.funcForObject(obj)
}

func (p *Project) writeConsistencyPlan(c IssueConcepts, cp *consistencyPlan) string {
	var b strings.Builder
	fmt.Fprintf(&b, "SITES — %s handling by package:\n", strings.Join(cp.concepts, "/"))
	for _, s := range cp.sites {
		fmt.Fprintf(&b, "  %s — ", s.pkg.Name)
		var parts []string
		for _, fn := range s.funcs {
			parts = append(parts, fmt.Sprintf("%s (%s:%d)",
				strings.TrimPrefix(fn.Sig, "func "), p.LinkPath(fn.File), fn.Line))
		}
		fmt.Fprintf(&b, "%s\n", strings.Join(parts, ", "))
	}
