	_, ok := b.List[len(b.List)-1].(*ast.ReturnStmt)
	return ok
}

// callerChain walks from fn up through its most important caller to a
// root, returning the chain root-first. It caps at max functions.
func callerChain(p *Project, fn *Func, max int) []*Func {
	chain := []*Func{fn}
	seen := map[string]bool{fn.ID: true}
	cur := fn
	for len(chain) < max {
		var best *Func
		for _, id := range cur.Callers {
			c := p.byID[id]
			if c == nil || seen[c.ID] {
				continue
			}

			if strings.HasSuffix(c.File, "_test.go") {
				continue
			}
			if best == nil || c.Score > best.Score {
				best = c
			}
		}
		if best == nil {
			break
		}
		seen[best.ID] = true
		chain = append([]*Func{best}, chain...)
		cur = best
	}

	for i, fn := range chain {
		if fn.IsMain {
			return chain[i:]
		}
	}
	return chain
}

// camelSplit splits "ServeHTTP" into ["Serve", "HTTP"], "userID" into
// ["user", "ID"]. Used to match task keywords against symbol names.
func camelSplit(s string) []string {
	var words []string
	start := 0
	runes := []rune(s)
	for i := 1; i <= len(runes); i++ {
		if i == len(runes) || (isUpper(runes[i]) && !isUpper(runes[i-1])) ||
			(isUpper(runes[i-1]) && i < len(runes) && !isUpper(runes[i])) {
			if i > start {
				words = append(words, string(runes[start:i]))
			}
			start = i
		}
	}
	return words
}

func camelToWords(s string) string {
	words := splitName(s)
	for i, w := range words {
		words[i] = strings.ToLower(w)
	}
	return strings.Join(words, " ")
}

// capExamples keeps the first n examples and counts the rest.
func capExamples(in []string, n int) ([]string, int) {
	if len(in) <= n {
		return in, 0
	}
	return in[:n], len(in) - n
}

func capitalize(s string) string {
	if s == "" {
		return ""
	}
	r := []rune(s)
	if r[0] >= 'a' && r[0] <= 'z' {
		r[0] -= 'a' - 'A'
	}
	return string(r)
}

// chainExamples follows an if/else-if chain and collects the conditions
// that compare against a literal, e.g. `if line == "/flow"`.
func chainExamples(fset *token.FileSet, src []byte, s *ast.IfStmt) ([]string, int, bool) {
	var conds []string
	cur := s
	for cur != nil {
		if comparesLiteral(cur.Cond) {
			conds = append(conds, "if "+truncateRunes(nodeText(fset, src, cur.Cond), 56))
		}
		els, ok := cur.Else.(*ast.IfStmt)
		if !ok {
			break
		}
		cur = els
	}
	ex, more := capExamples(conds, 5)
	return ex, more, true
}

// checkGuard returns the first flag-like guard condition: the option
// the function honors.
func checkGuard(fn *Func) string {
	for _, g := range fn.Guards {
		if g.FlagLike {
			return g.Cond
		}
	}
	return ""
}

// childStmtLists returns nested statement lists for recursion into
// loops, switches, and selects.
func childStmtLists(stmt ast.Stmt) [][]ast.Stmt {
	var out [][]ast.Stmt
	switch s := stmt.(type) {
	case *ast.ForStmt:
		out = append(out, s.Body.List)
	case *ast.RangeStmt:
		out = append(out, s.Body.List)
	case *ast.SwitchStmt:
		for _, c := range s.Body.List {
			if cc, ok := c.(*ast.CaseClause); ok {
				out = append(out, cc.Body)
			}
		}
	case *ast.TypeSwitchStmt:
		for _, c := range s.Body.List {
			if cc, ok := c.(*ast.CaseClause); ok {
				out = append(out, cc.Body)
			}
		}
	case *ast.SelectStmt:
		for _, c := range s.Body.List {
			if cc, ok := c.(*ast.CommClause); ok {
				out = append(out, cc.Body)
			}
		}
	}
	return out
}

// cleanSymbol strips articles, quotes, and role words from a symbol name.
// It never invents a symbol: a multi-word phrase that isn't a known
// "X function" / "X method" form is returned as-is and won't resolve,
// so e.g. "what does make chat do" can't become "chat".
func cleanSymbol(s string) string {
	s = strings.TrimSpace(s)
	s = strings.Trim(s, `"'().,?!`)
	s = strings.TrimPrefix(s, "the ")
	for _, w := range []string{" function", " func", " method", " type", " struct", " package"} {
		s = strings.TrimSuffix(s, w)
	}
	return strings.TrimSpace(strings.Trim(s, `"'().,?!`))
}

// coherent reports whether a concept's matches look like each other:
// the most common non-concept, non-stopword name token recurs in at
// least half the matches. CheckForWin/CheckWin cohere ("check");
// buildGameGrid/handleGameProgressTick don't.
func coherent(concept string, funcs []*Func) bool {
	if len(funcs) == 0 {
		return false
	}
	toks := map[string]int{}
	for _, fn := range funcs {
		for _, t := range tokenizeName(fn.Name) {
			if t == concept || planStopwords[t] {
				continue
			}
			toks[t]++
		}
	}
	for _, n := range toks {
		if n*2 >= len(funcs) {
			return true
		}
	}
	return false
}

func commas(n int) string {
	s := fmt.Sprintf("%d", n)
	var out []byte
	for i, c := range s {
		if i > 0 && (len(s)-i)%3 == 0 {
			out = append(out, ',')
		}
		out = append(out, byte(c))
	}
	return string(out)
}

// commonDir returns the deepest shared directory of the given dirs.
func commonDir(dirs []string) string {
	if len(dirs) == 0 {
		return ""
	}
	split := func(d string) []string { return strings.Split(d, "/") }
	parts := split(dirs[0])
	for _, d := range dirs[1:] {
		sp := split(d)
		i := 0
		for i < len(parts) && i < len(sp) && parts[i] == sp[i] {
			i++
		}
		parts = parts[:i]
	}
	return strings.Join(parts, "/")
}

// commonReceiver returns the receiver name the type's methods use.
func commonReceiver(methods []*Func) string {
	counts := map[string]int{}
	best, bestN := "", 0
	for _, m := range methods {

		if i := strings.Index(m.Sig, "("); i >= 0 {
			rest := m.Sig[i+1:]
			if j := strings.IndexAny(rest, " )"); j > 0 {
				name := rest[:j]
				counts[name]++
				if counts[name] > bestN {
					best, bestN = name, counts[name]
				}
			}
		}
	}
	if best == "" {
		best = "x"
	}
	return best
}

// comparesLiteral reports whether e is `x == "lit"` or `"lit" == x`.
func comparesLiteral(e ast.Expr) bool {
	bin, ok := e.(*ast.BinaryExpr)
	if !ok {
		return false
	}
	if bin.Op != token.EQL && bin.Op != token.NEQ {
		return false
	}
	_, lLit := bin.X.(*ast.BasicLit)
	_, rLit := bin.Y.(*ast.BasicLit)
	return lLit || rLit
}

// compositeTypeName renders the type of a composite literal expression:
// &config.Config{...} or config.Config{...} -> "config.Config".
func compositeTypeName(pkg *Package, e ast.Expr) string {
	if u, ok := e.(*ast.UnaryExpr); ok && u.Op == token.AND {
		e = u.X
	}
	if cl, ok := e.(*ast.CompositeLit); ok {
		return paramTypeName(pkg, cl.Type)
	}
	return ""
}

// constructorVars maps local variable names to import aliases for the
// common constructor pattern: s := store.New(). This lets s.Save()
// resolve to the Save method in the store package without type info.
func constructorVars(body *ast.BlockStmt, pkg *Package) map[string]string {
	out := map[string]string{}
	ast.Inspect(body, func(n ast.Node) bool {
		assign, ok := n.(*ast.AssignStmt)
		if !ok || len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
			return true
		}
		lhs, ok := assign.Lhs[0].(*ast.Ident)
		if !ok {
			return true
		}
		call, ok := assign.Rhs[0].(*ast.CallExpr)
		if !ok {
			return true
		}
		sel, ok := call.Fun.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		if id, ok := sel.X.(*ast.Ident); ok {
			if _, isAlias := pkg.aliasCache[id.Name]; isAlias {
				out[lhs.Name] = id.Name
			}
		}
		return true
	})
	return out
}

func contains(ss []string, s string) bool {
	for _, x := range ss {
