// docText flattens a comment group to one line.
func docText(cg *ast.CommentGroup) string {
	if cg == nil {
		return ""
	}
	t := strings.TrimSpace(cg.Text())
	t = strings.Join(strings.Fields(t), " ")
	if len(t) > 220 {
		t = t[:217] + "..."
	}
