// effectPhrases renders a function's direct effects in plain words:
// "writes files (os.WriteFile)".
func effectPhrases(fn *Func) []string {
	var writes, reads, net []string
	for _, e := range fn.ExtCalls {
		for _, fx := range callEffects[e] {
			switch fx {
			case fxWrite:
				writes = append(writes, e)
			case fxRead:
				reads = append(reads, e)
			case fxNet:
				net = append(net, e)
			}
		}
	}
	var out []string
	if len(writes) > 0 {
		out = append(out, "writes files ("+strings.Join(writes, ", ")+")")
	}
	if len(reads) > 0 {
		out = append(out, "reads files ("+strings.Join(reads, ", ")+")")
	}
	if len(net) > 0 {
		out = append(out, "uses the network ("+strings.Join(net, ", ")+")")
	}
	return out
}

// existingPaths returns the issue's backticked paths that exist on disk:
// the files (or directories) the change touches.
func existingPaths(p *Project, c IssueConcepts) []string {
	var out []string
	seen := map[string]bool{}
	for _, w := range c.CodeWords {
		w = strings.Trim(w, "`\"' ")
		if !isPathWord(w) || seen[w] {
			continue
		}
		seen[w] = true
		full := filepath.Join(p.Root, filepath.FromSlash(strings.TrimSuffix(w, "/")))
		if _, err := os.Stat(full); err == nil {
			out = append(out, strings.TrimSuffix(w, "/"))
		}
	}
	return out
}

// exprName renders a receiver/field type expression to a short name.
func exprName(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.StarExpr:
		return exprName(t.X)
	case *ast.IndexExpr:
		return exprName(t.X)
	case *ast.IndexListExpr:
		return exprName(t.X)
	case *ast.SelectorExpr:
		return t.Sel.Name
	}
	return ""
}

// extCallKey maps a call like os.Remove(x) to "os.Remove" when the
// qualifier is an imported external package. Returns "" for project
// packages, unqualified calls, and unknown qualifiers. Dot-imports and
// explicit aliases ("o \"os\"") are not resolved — accepted heuristic gap.
func extCallKey(pkg *Package, call *ast.CallExpr) string {
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return ""
	}
	id, ok := sel.X.(*ast.Ident)
	if !ok {
		return ""
	}
	if _, isProj := pkg.aliasCache[id.Name]; isProj {
		return ""
	}
	for _, imp := range pkg.Imports {
		if importBase(imp) == id.Name {
			return id.Name + "." + sel.Sel.Name
		}
	}
	return ""
}

// fieldListString renders "a int, b string" for a parameter/result list.
func fieldListString(fields []*ast.Field) string {
	var parts []string
	for _, f := range fields {
		t := typeString(f.Type)
		if len(f.Names) == 0 {
			parts = append(parts, t)
			continue
		}
		var names []string
		for _, n := range f.Names {
			names = append(names, n.Name)
		}
		parts = append(parts, strings.Join(names, ", ")+" "+t)
	}
	return strings.Join(parts, ", ")
}

// fieldNames collects declared field/method names from a field list.
func fieldNames(fl *ast.FieldList) []string {
	var out []string
	if fl == nil {
		return out
	}
	for _, f := range fl.List {
		for _, n := range f.Names {
			out = append(out, n.Name)
		}

		if len(f.Names) == 0 {
			if id := exprName(f.Type); id != "" {
				out = append(out, id)
			}
		}
	}
	return out
}

func filepathBase(p string) string {
	if i := strings.LastIndex(p, "/"); i >= 0 {
		return p[i+1:]
	}
	return p
}

// findDispatchSites parses the anchor's file and looks for extension
// points in its body: switch statements and if/else chains that compare
// against literals — the shapes where new cases get added.
func findDispatchSites(root string, fn *Func) []dispatchSite {
	src, err := os.ReadFile(filepath.Join(root, fn.File))
	if err != nil {
		return nil
	}
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, fn.File, src, 0)
	if err != nil {
		return nil
	}
	decl := findFuncDecl(file, fn)
	if decl == nil || decl.Body == nil {
		return nil
	}
	var sites []dispatchSite
	ast.Inspect(decl.Body, func(n ast.Node) bool {
		switch s := n.(type) {
		case *ast.SwitchStmt:
			if ex, more := switchExamples(fset, src, s); len(ex) >= 2 {
				sites = append(sites, dispatchSite{
					kind:		"switch",
					line:		fset.Position(s.Pos()).Line,
					examples:	ex,
					more:		more,
				})
			}
		case *ast.IfStmt:
			if ex, more, ok := chainExamples(fset, src, s); ok && len(ex) >= 2 {
				sites = append(sites, dispatchSite{
					kind:		"chain",
					line:		fset.Position(s.Pos()).Line,
					examples:	ex,
					more:		more,
				})
			}
		}
		return true
	})
	return sites
}

// findFlagsFunc finds the flag-parsing function in the config package:
// a name with "flag" in it, else a file with "flag" in its name.
func findFlagsFunc(pkg *Package) *Func {
	for _, fn := range pkg.Funcs {
		if !fn.IsTest && strings.Contains(strings.ToLower(fn.Name), "flag") {
			return fn
		}
	}
	for _, fn := range pkg.Funcs {
		if !fn.IsTest && strings.Contains(strings.ToLower(fn.File), "flag") {
			return fn
		}
	}
	return nil
}

// findFuncDecl locates the declaration matching fn by name and receiver.
func findFuncDecl(file *ast.File, fn *Func) *ast.FuncDecl {
	var found *ast.FuncDecl
	ast.Inspect(file, func(n ast.Node) bool {
		d, ok := n.(*ast.FuncDecl)
		if !ok || d.Name.Name != fn.Name {
			return true
		}
		hasRecv := d.Recv != nil && len(d.Recv.List) > 0
		if (fn.Receiver != "") != hasRecv {
			return true
		}
		found = d
		return false
	})
	return found
}

// findModule reads the module path from the nearest go.mod at or above dir.
func findModule(dir string) string {
	for d := dir; ; d = filepath.Dir(d) {
		data, err := os.ReadFile(filepath.Join(d, "go.mod"))
		if err == nil {
			for _, line := range strings.Split(string(data), "\n") {
				if rest, ok := strings.CutPrefix(strings.TrimSpace(line), "module "); ok {
					return strings.TrimSpace(rest)
				}
			}
			return ""
		}
		parent := filepath.Dir(d)
		if parent == d {
			return ""
		}
	}
}

func firstLine(s string) string {
	if i := strings.IndexByte(s, '\n'); i >= 0 {
		return s[:i]
	}
	return s
}

// firstSentence returns the first sentence of s, trimmed.
func firstSentence(s string) string {
	s = strings.TrimSpace(s)
	if s == "" {
		return ""
	}
	for i, r := range s {
		if r == '.' || r == '!' || r == '?' {
			if i+1 >= len(s) || s[i+1] == ' ' {
				return strings.TrimSpace(s[:i+1])
			}
		}
	}
	if len(s) > 140 {
		return s[:137] + "..."
	}
	return s
}

// flagLikeCond reports whether a condition reads like an option/flag
// check: a bare bool parameter (if dryRun), a selector on a parameter
// typed by a project package (if cfg.DryRun), or a local alias of such
// a value (dry := cfg.DryRun; if dry). err != nil and friends don't
// match any shape.
func flagLikeCond(cond ast.Expr, paramNames map[string]bool, paramPkgs map[string]*Package, aliasOf map[string]string) bool {
	for {
		switch c := cond.(type) {
		case *ast.ParenExpr:
			cond = c.X
		case *ast.UnaryExpr:
			cond = c.X
		default:
			goto done
		}
	}
done:
	switch c := cond.(type) {
	case *ast.Ident:
		return paramNames[c.Name] || aliasOf[c.Name] != ""
	case *ast.SelectorExpr:
		if id, ok := c.X.(*ast.Ident); ok {
			_, isParam := paramPkgs[id.Name]
			return isParam || paramNames[id.Name]
		}
	}
	return false
}

// flagsSignal reports whether the issue talks about user-facing options.
func flagsSignal(c IssueConcepts) bool {
	for _, w := range c.CodeWords {
		if strings.HasPrefix(w, "--") {
			return true
		}
	}
	lower := strings.ToLower(c.Title + "\n" + c.Body)
	for _, w := range []string{"flag", "option", "cli"} {
		if strings.Contains(lower, w) {
			return true
		}
	}
	return false
}

// funcID builds the unique ID for a function or method.
func funcID(dir, recv, name string) string {
	base := dir
	if base == "" {
		base = "root"
	}
	base = strings.ReplaceAll(base, string(filepath.Separator), ".")
	if recv != "" {
		return base + "." + recv + "." + name
	}
	return base + "." + name
}

// hasBenchmark reports whether a test file defines a Benchmark function.
func hasBenchmark(full string) bool {
	src, err := os.ReadFile(full)
	if err != nil {
		return false
	}
	return strings.Contains(string(src), "func Benchmark")
}

func hasEffect(cats []string, want string) bool {
	for _, c := range cats {
		if c == want {
			return true
		}
	}
	return false
}

// importBase is the qualifier a selector would use: the last path element.
func importBase(imp string) string {
	if i := strings.LastIndex(imp, "/"); i >= 0 {
		return imp[i+1:]
	}
	return imp
}

func inLoopRange(call *ast.CallExpr, loops [][2]int) bool {
	pos, end := int(call.Pos()), int(call.End())
	for _, r := range loops {
		if pos >= r[0] && end <= r[1] {
			return true
		}
	}
	return false
}

func isCache(fn *Func) bool {

	return len(fn.Reads) > 0 && len(fn.Writes) > 0
}

func isConstructor(name string) bool {
	return strings.HasPrefix(name, "New")
}

func isExported(name string) bool {
	return name != "" && name[0] >= 'A' && name[0] <= 'Z'
}

func isGetter(fn *Func) bool {

	if fn.Params != 0 || fn.Receiver == "" || fn.Name == "Close" {
		return false
	}
	name := fn.Name
	if strings.HasPrefix(name, "Get") {
		rest := strings.TrimPrefix(name, "Get")
		if rest == "" || rest[0] < 'A' || rest[0] > 'Z' {
			return false
		}
		name = rest
	}
	words := splitName(name)
	if len(words) != 1 {
		return false
	}

	return strings.Contains(fn.Sig, ") ") && !strings.HasSuffix(fn.Sig, "()")
}

func isHTTPHandler(fn *Func) bool {
	for _, t := range fn.ParamTypes {

		if strings.HasSuffix(t, "ResponseWriter") {
			return true
		}
	}
	return false
}

// isPathWord reports whether a backticked word looks like a repo path:
// has a slash, no whitespace, not a URL or module path (first segment
// has no dot, so golang.org/x/sys is out), and looks like a file or
// directory (trailing slash, .go suffix, or at least two slashes — so
// allocs/op is out).
func isPathWord(w string) bool {
	if !strings.Contains(w, "/") || strings.ContainsAny(w, " \t\n") ||
		strings.Contains(w, "://") {
		return false
	}
	if strings.Contains(strings.Split(w, "/")[0], ".") {
		return false
	}
	if strings.HasSuffix(w, "/") || strings.HasSuffix(w, ".go") {
		return true
	}
	return strings.Count(w, "/") >= 2
}

func isPredicate(fn *Func) bool {
	if !strings.Contains(fn.Sig, ") bool") {
		return false
	}
	for _, prefix := range []string{"Is", "Has", "Can", "Should", "Needs", "Wants"} {
		if strings.HasPrefix(fn.Name, prefix) {
			rest := strings.TrimPrefix(fn.Name, prefix)
			return rest != "" && rest[0] >= 'A' && rest[0] <= 'Z'
		}
	}
	return false
}

func isRetryLoop(fn *Func) bool {

	if len(fn.LoopCalls) == 0 {
		return false
	}
	sleeps := false
	for _, e := range fn.ExtCalls {
		if e == "time.Sleep" {
			sleeps = true
			break
		}
	}
	return sleeps
}

func isSetter(fn *Func) bool {

	if !strings.HasPrefix(fn.Name, "Set") || fn.Params < 1 {
		return false
	}
	rest := strings.TrimPrefix(fn.Name, "Set")
	return rest != "" && rest[0] >= 'A' && rest[0] <= 'Z'
}

func isValidatorName(name string) bool {
	lower := strings.ToLower(name)
	return strings.Contains(lower, "valid") || strings.Contains(lower, "check") ||
		strings.Contains(lower, "verify") || strings.HasPrefix(lower, "is") ||
		strings.HasPrefix(lower, "has")
}

// isVisualWord keeps "show me a visual" out of the symbol path.
func isVisualWord(s string) bool {
	switch strings.ToLower(s) {
	case "visual", "graph", "diagram", "picture", "map":
		return true
	}
	return false
}

func issueTitle(text string) string {
	for _, line := range strings.Split(text, "\n") {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		line = strings.TrimPrefix(line, "#")
		line = strings.TrimSpace(line)
		for _, p := range []string{"Feature Request:", "Feature request:", "Bug:", "Issue:"} {
			if strings.HasPrefix(line, p) {
				line = strings.TrimSpace(strings.TrimPrefix(line, p))
			}
		}
		if len(line) > 80 {
			line = line[:77] + "..."
		}
		return line
	}
	return "this change"
}

// joinShort renders callee/caller ID lists, capped at n with a "+k more".
func joinShort(ids []string, n int) string {
	var names []string
	for _, id := range ids {
		names = append(names, shortID(id))
	}
	sort.Strings(names)
	if len(names) > n {
		return strings.Join(names[:n], ", ") + fmt.Sprintf(" (+%d more)", len(names)-n)
	}
	return strings.Join(names, ", ")
}

func joinWithAnd(parts []string) string {
	if len(parts) <= 2 {
		return strings.Join(parts, " and ")
	}
	return strings.Join(parts[:len(parts)-1], ", ") + ", and " + parts[len(parts)-1]
}

// joinWords joins names as "a, b and c".
func joinWords(names []string) string {
	switch len(names) {
	case 0:
		return ""
	case 1:
		return names[0]
	case 2:
		return names[0] + " and " + names[1]
	default:
		return strings.Join(names[:len(names)-1], ", ") + " and " + names[len(names)-1]
	}
}

// keyFuncOf returns the most-called function in a package.
func keyFuncOf(p *Project, pkg *Package) *Func {
	var key *Func
	most := -1
	for _, fn := range pkg.Funcs {
		if len(fn.Callers) > most {
			most, key = len(fn.Callers), fn
		}
	}
	return key
}

// keyLiterals normalizes the issue's backticked hotkeys (`Ctrl+A`)
// into the case-literal form the code uses ("ctrl+a").
func keyLiterals(c IssueConcepts) []string {
	var out []string
	seen := map[string]bool{}
	for _, w := range c.CodeWords {
		k := strings.ToLower(strings.TrimSpace(w))
		if k == "" || seen[k] {
			continue
		}
		seen[k] = true
		if keyLikeRe.MatchString(k) || strings.Contains(k, "+") {
			out = append(out, k)
		}
	}
	return out
}

func limitStr(ss []string, n int) []string {
	if len(ss) > n {
		return ss[:n]
	}
	return ss
}

// loopRanges returns the [pos, end) offsets of for/range loop bodies,
// so calls made per-iteration (the per-item hooks) can be told apart
// from calls evaluated once like the range expression itself.
func loopRanges(body *ast.BlockStmt) [][2]int {
	var ranges [][2]int
	ast.Inspect(body, func(n ast.Node) bool {
		switch x := n.(type) {
		case *ast.ForStmt:
			ranges = append(ranges, [2]int{int(x.Body.Pos()), int(x.Body.End())})
		case *ast.RangeStmt:
			ranges = append(ranges, [2]int{int(x.Body.Pos()), int(x.Body.End())})
		}
		return true
	})
	return ranges
}

// methodName extracts the new method's name: "Implement Info method"
// -> "Info". Generic verbs ("Add method", "new method") don't count.
func methodName(c IssueConcepts) string {
	for _, m := range methodRe.FindAllStringSubmatch(c.Title, -1) {
		n := m[1]
		if planStopwords[strings.ToLower(n)] {
			continue
		}
		return strings.ToUpper(n[:1]) + n[1:]
	}
	return ""
}

// missingPaths returns the issue's backticked paths that don't exist in
// the repo: the issue telling us where to create.
func missingPaths(p *Project, c IssueConcepts) []string {
	var out []string
	seen := map[string]bool{}
	for _, w := range c.CodeWords {
		w = strings.Trim(w, "`\"' ")
		if !isPathWord(w) || seen[w] {
			continue
		}
		seen[w] = true
		full := filepath.Join(p.Root, filepath.FromSlash(strings.TrimSuffix(w, "/")))
		if _, err := os.Stat(full); os.IsNotExist(err) {
			out = append(out, w)
		}
	}
	return out
}

// namedCalls returns backticked pkg.Func words: external calls the issue
// talks about, e.g. os.ReadFile.
func namedCalls(c IssueConcepts) []string {
	var out []string
	seen := map[string]bool{}
	for _, w := range c.CodeWords {
		w = strings.Trim(w, "`\"' ")
		if seen[w] || strings.Contains(w, "/") {
			continue
		}
		parts := strings.SplitN(w, ".", 2)
		if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
			continue
		}
		c0, c1 := rune(parts[0][0]), rune(parts[1][0])
		if !(c0 >= 'a' && c0 <= 'z') || !(c1 >= 'A' && c1 <= 'Z') {
			continue
		}
		seen[w] = true
		out = append(out, w)
	}
	return out
}

// namedTypeName extracts "Store" from *pkg.Store or pkg.Store.
func namedTypeName(t types.Type) string {
	if ptr, ok := t.(*types.Pointer); ok {
		t = ptr.Elem()
	}
	if named, ok := t.(*types.Named); ok {
		return named.Obj().Name()
	}
	return ""
}

// newFlags returns the issue's --flags not already covered by the Config
// struct's fields: those are the options being added.
func newFlags(c IssueConcepts, t *Type) []string {
	fieldToks := map[string]bool{}
	for _, f := range t.Fields {
		for _, tok := range tokenizeName(f) {
			fieldToks[tok] = true
		}
	}
	var out []string
	seen := map[string]bool{}
	for _, w := range c.CodeWords {
		m := flagWordRe.FindStringSubmatch(w)
		if m == nil || seen[m[0]] {
			continue
		}
		seen[m[0]] = true
		covered := true
		for _, tok := range wordTokens(m[1]) {
			if !fieldToks[tok] {
				covered = false
				break
			}
		}
		if !covered {
			out = append(out, "--"+m[1])
		}
	}
	return out
}

