// planNoun names the feature's artifact from the issue's own --flags:
// --report and --report-format agree on "report".
func planNoun(c IssueConcepts) string {
	counts := map[string]int{}
	best, bestN := "", 0
	for _, w := range c.CodeWords {
		m := flagWordRe.FindStringSubmatch(w)
		if m == nil {
			continue
		}
		noun := strings.Split(m[1], "-")[0]
		if len(noun) < 3 {
			continue
		}
		counts[noun]++
		if counts[noun] > bestN {
			bestN, best = counts[noun], noun
		}
	}
	return best
}

func predicatePhrase(name string) string {
	for _, prefix := range []string{"Is", "Has", "Can", "Should", "Needs", "Wants"} {
		if strings.HasPrefix(name, prefix) {
			rest := strings.TrimPrefix(name, prefix)
			words := camelToWords(rest)
			switch prefix {
			case "Is":
				return words
			case "Has":
				return "it has " + words
			case "Can":
				return "it can " + words
			default:
				return words
			}
		}
	}
	return camelToWords(name)
}

// problemStatement distills the issue body into a short problem
// description: the first meaningful lines after stripping the title,
// markdown headers, code fences, and unfilled template boilerplate.
func problemStatement(c IssueConcepts) string {
	body := fenceRe.ReplaceAllString(c.Body, "")
	title := strings.TrimSpace(c.Title)
	var keep []string
	for _, ln := range strings.Split(body, "\n") {
		t := strings.TrimSpace(ln)
		if t == "" || t == title {
			continue
		}
		if strings.HasPrefix(t, "A clear and concise description") {
			continue
		}
		if strings.HasPrefix(t, "#") ||
			(strings.HasPrefix(t, "**") && strings.HasSuffix(t, "**")) {

			if len(keep) > 0 {
				break
			}
			continue
		}
		keep = append(keep, t)
		if len(keep) >= 3 {
			break
		}
	}
	s := strings.Join(strings.Fields(strings.Join(keep, " ")), " ")
	if len(s) > 400 {
		s = s[:397] + "..."
	}
	if s == "" {
		return title
	}
	return s
}

