// splitName splits a CamelCase identifier for intent reading:
// "DeleteFile" -> ["Delete", "File"], "ServeHTTP" -> ["Serve", "HTTP"],
// "Copy" -> ["Copy"]. (The shared camelSplit over-splits single words.)
func splitName(s string) []string {
	var words []string
	start := 0
	runes := []rune(s)
	isUpper := func(r rune) bool { return r >= 'A' && r <= 'Z' }
	isLower := func(r rune) bool { return r >= 'a' && r <= 'z' }
	for i := 1; i < len(runes); i++ {
		r, prev := runes[i], runes[i-1]
		split := false
		switch {
		case isUpper(r) && (isLower(prev) || prev >= '0' && prev <= '9'):
			split = true
		case isUpper(r) && isUpper(prev) && i+1 < len(runes) && isLower(runes[i+1]):
			split = true
		}
		if split {
			words = append(words, string(runes[start:i]))
			start = i
		}
	}
	words = append(words, string(runes[start:]))
	return words
}

func startsWithArticle(s string) bool {
	lower := strings.ToLower(s)
	return strings.HasPrefix(lower, "a ") || strings.HasPrefix(lower, "an ") ||
		strings.HasPrefix(lower, "the ")
}

// stem reduces a word to a crude root so "deletion", "delete" and
// "deleted" match each other.
func stem(w string) string {
	w = strings.ToLower(w)

	if strings.HasSuffix(w, "es") && len(w) > 4 {
		for _, suf := range []string{"ses", "xes", "zes", "ches", "shes"} {
			if strings.HasSuffix(w, suf) {
				return w[:len(w)-2]
			}
		}
	}
	for _, suf := range []string{"ing", "ion", "ed", "s"} {
		if strings.HasSuffix(w, suf) && len(w) > len(suf)+2 {
			if suf == "s" && strings.HasSuffix(w, "ss") {
				continue
			}
			return w[:len(w)-len(suf)]
		}
	}
	return w
}

// switchExamples collects the case labels of a switch, truncated.
func switchExamples(fset *token.FileSet, src []byte, s *ast.SwitchStmt) ([]string, int) {
	var labels []string
	for _, stmt := range s.Body.List {
		cc, ok := stmt.(*ast.CaseClause)
		if !ok {
			continue
		}
		for _, e := range cc.List {
			if lit, ok := e.(*ast.BasicLit); ok {
				labels = append(labels, "case "+lit.Value+":")
			}
		}
	}
	return capExamples(labels, 5)
}

