func testIntent(name string) string {
	rest := strings.TrimPrefix(name, "Test")
	subj, extra := rest, ""
	if i := strings.Index(rest, "_"); i >= 0 {
		subj = rest[:i]
		extra = strings.ToLower(strings.ReplaceAll(rest[i+1:], "_", " "))
	}
	if extra != "" {
		return fmt.Sprintf("Tests %s (%s).", subj, extra)
	}
	return fmt.Sprintf("Tests %s.", subj)
}

// thirdPerson renders an infinitive verb in third person:
// "copy" -> "copies", "watch" -> "watches", "delete" -> "deletes".
func thirdPerson(v string) string {
	if v == "back up" {
		return "backs up"
	}
	if len(v) >= 2 && strings.HasSuffix(v, "y") &&
		!strings.ContainsRune("aeiou", rune(v[len(v)-2])) {
		return v[:len(v)-1] + "ies"
	}
	for _, suf := range []string{"s", "x", "z", "ch", "sh"} {
		if strings.HasSuffix(v, suf) {
			return v + "es"
		}
	}
	return v + "s"
}

// titleNouns returns the significant stemmed words of the issue title,
// plus the unstemmed words for display.
func titleNouns(title string) (stems, words []string) {
	seen := map[string]bool{}
	for _, w := range strings.FieldsFunc(strings.ToLower(title),
		func(r rune) bool { return r < 'a' || r > 'z' }) {
		if len(w) < 3 || planStopwords[w] {
			continue
		}
		s := stem(w)
		if !seen[s] {
			seen[s] = true
			stems = append(stems, s)
			words = append(words, w)
		}
	}
	return stems, words
}

// tokenizeName splits a camelCase identifier into stemmed words:
// WriteJSONLog -> [write json log], LogDeletionToFileAsJson ->
// [log delet to file as json]. Consecutive capitals stay together
// unless followed by a lowercase letter (JSONLog -> JSON + Log).
func tokenizeName(name string) []string {
	isUpper := func(r rune) bool { return r >= 'A' && r <= 'Z' }
	isLower := func(r rune) bool { return r >= 'a' && r <= 'z' }
	isDigit := func(r rune) bool { return r >= '0' && r <= '9' }
	runes := []rune(name)
	var toks []string
	start := 0
	flush := func(end int) {
		if w := stem(string(runes[start:end])); w != "" {
			toks = append(toks, w)
		}
		start = end
	}
	for i := 1; i < len(runes); i++ {
		r, prev := runes[i], runes[i-1]
		switch {
		case r == '_' || r == '-':
			flush(i)
			start = i + 1
		case isUpper(r) && (isLower(prev) || isDigit(prev)):
			flush(i)
		case isUpper(r) && isUpper(prev) && i+1 < len(runes) && isLower(runes[i+1]):
			flush(i)
		case (isDigit(r) && !isDigit(prev)) || (!isDigit(r) && isDigit(prev)):
			flush(i)
		}
	}
	flush(len(runes))
	return toks
}

// topNew picks the proposed-new keys worth naming: short config-ish
// words first (retry, limit), not values or prose.
func topNew(keys []string, n int) []string {
	var good, rest []string
	for _, k := range keys {
		if len(k) <= 12 && !strings.ContainsAny(k, "_-") {
			good = append(good, k)
		} else {
			rest = append(rest, k)
		}
	}
	out := append(good, rest...)
	if len(out) > n {
		out = out[:n]
	}
	return out
}

// truncateRunes shortens s to at most n runes.
func truncateRunes(s string, n int) string {
	r := []rune(s)
	if len(r) <= n {
		return s
	}
	return strings.TrimSpace(string(r[:n-1])) + "…"
}

// typeString renders a type expression in short Go syntax.
func typeString(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.StarExpr:
		return "*" + typeString(t.X)
	case *ast.SelectorExpr:
		return typeString(t.X) + "." + t.Sel.Name
	case *ast.ArrayType:
		if t.Len == nil {
			return "[]" + typeString(t.Elt)
		}
		return "[...]" + typeString(t.Elt)
	case *ast.Ellipsis:
		return "..." + typeString(t.Elt)
	case *ast.MapType:
		return "map[" + typeString(t.Key) + "]" + typeString(t.Value)
	case *ast.ChanType:
		return "chan " + typeString(t.Value)
	case *ast.FuncType:
		return "func(...)"
	case *ast.InterfaceType:
		if t.Methods == nil || len(t.Methods.List) == 0 {
			return "any"
		}
		return "interface{...}"
	case *ast.StructType:
		return "struct{...}"
	case *ast.ParenExpr:
		return typeString(t.X)
	}
	return ""
}

// valueTypeOf resolves the "pkg.Type" of a parameter, receiver, or local
// variable name. Empty when the type isn't a named struct/pointer shape.
func valueTypeOf(fn *Func, name string) string {
	if t := fn.ParamTypes[name]; t != "" {
		return t
	}
	return fn.localTypes[name]
}

// verbPhrase turns a function name into a plain verb phrase:
// "DeleteFile" -> "deletes a file" (third=true) or "delete a file"
// (third=false, for "why does X call Y" — "to delete a file").
// "CopyOrCloneFile" -> "copies or clones a file".
func verbPhrase(name string, third bool) string {
	words := splitName(name)
	var parts []string
	i := 0
	for ; i < len(words); i++ {
		w := words[i]
		if w == "Or" || w == "And" {
			parts = append(parts, strings.ToLower(w))
			continue
		}
		v, ok := verbLexicon[w]
		if !ok {
			break
		}
		if third {
			v = thirdPerson(v)
		}
		parts = append(parts, v)
	}
	rest := words[i:]
	if len(parts) == 0 {
		return "handles " + articleJoin(rest)
	}
	out := strings.Join(parts, " ")
	if len(rest) > 0 {
		out += " " + articleJoin(rest)
	}
	return out
}

