func wordTokens(s string) []string {
	var out []string
	for _, w := range strings.FieldsFunc(strings.ToLower(s),
		func(r rune) bool { return r < 'a' || r > 'z' }) {
		if len(w) >= 2 {
			out = append(out, stem(w))
		}
	}
	return out
}

