// NewLinear creates a new Linear layer with random weights and zero biases.
func NewLinear(inputDim, outputDim int) (*Linear, error) {

	stdDev := float32(math.Sqrt(2.0 / float64(inputDim)))
	weightsData := make([]float32, inputDim*outputDim)
	wi := newWeightIterator(weightsData, inputDim, outputDim)
	for wi.Next() {
		idx := wi.GetIndex()
		weightsData[idx] = float32(rand.NormFloat64()) * stdDev
	}

	weights := NewTensor([]int{inputDim, outputDim}, weightsData, true)
	weights.RequiresGrad = true

	biasesData := make([]float32, outputDim)
	biases := NewTensor([]int{outputDim}, biasesData, true)
	biases.RequiresGrad = true

	return &Linear{Weights: weights, Biases: biases}, nil
}

// NewMoE creates a mixture of numExperts experts with top-k routing.
func NewMoE(hiddenDim, numExperts, topK, expertDim int) (*MoE, error) {
	if numExperts < 1 || topK < 1 || topK > numExperts {
		return nil, fmt.Errorf("moe: invalid numExperts=%d topK=%d", numExperts, topK)
	}
	router, err := NewLinear(hiddenDim, numExperts)
	if err != nil {
		return nil, fmt.Errorf("moe router: %w", err)
	}
	experts := make([]*Expert, numExperts)
	for i := range experts {
		experts[i], err = NewExpert(hiddenDim, expertDim)
		if err != nil {
			return nil, fmt.Errorf("moe expert %d: %w", i, err)
		}
	}
	return &MoE{
		NumExperts:	numExperts,
		TopK:		topK,
		HiddenDim:	hiddenDim,
		ExpertDim:	expertDim,
		Router:		router,
		Experts:	experts,
	}, nil
}

