// topKCandidates returns the text of the k highest-logit tokens.
func topKCandidates(logits []float32, k int, v *vocab.Vocabulary) []string {
	type pair struct {
		id	int
		v	float32
	}
	best := make([]pair, 0, k)
	for i, lv := range logits {
		inserted := false
		for j := range best {
			if lv > best[j].v {
				best = append(best, pair{})
				copy(best[j+1:], best[j:])
				best[j] = pair{i, lv}
				inserted = true
				break
			}
		}
		if !inserted && len(best) < k {
			best = append(best, pair{i, lv})
		}
		if len(best) > k {
			best = best[:k]
		}
	}
	out := make([]string, 0, len(best))
	for _, b := range best {
		out = append(out, v.GetWord(b.id))
	}
	return out
}

// CreateAndSaveVocab creates a vocabulary from a list of token slices and saves it as a GOB file.
func CreateAndSaveVocab(sentences [][]string, vocabPath string) (*Vocabulary, error) {
	tokenVocab := NewVocabulary()
	for _, tokens := range sentences {
		for _, token := range tokens {
			tokenVocab.AddToken(token)
		}
	}

	err := tokenVocab.Save(vocabPath)
	if err != nil {
		return nil, fmt.Errorf("failed to save vocabulary: %w", err)
	}

	return tokenVocab, nil
}

