// L2Norm calculates the L2 norm (Euclidean norm) of the tensor's data.
func (t *Tensor) L2Norm() float32 {
	if len(t.Data) == 0 {
		return 0
	}
	var normSq float64
	for _, v := range t.Data {
		normSq += float64(v * v)
	}
	return float32(math.Sqrt(normSq))
}

