// Decode converts a slice of token IDs back into a string using the tagger/vocab Vocabulary.
// This version is JSON-aware and does not add extra spaces or punctuation.
func (t *Tokenizer) Decode(tokenIDs []int) (string, error) {
	if t.Vocabulary == nil {
		return "", errors.New("tokenizer's vocabulary is not set")
	}

	var sb strings.Builder
	var lastToken string
	for _, id := range tokenIDs {

		word := t.Vocabulary.GetWord(id)
		if word == "" {
			word = fmt.Sprintf("[%d]", id)
		}

		if sb.Len() > 0 && !isJSONPunct(lastToken) && !isJSONPunct(word) {
			sb.WriteString(" ")
		}
		sb.WriteString(word)
		lastToken = word
	}

	return sb.String(), nil
}

// Encode converts a string into a slice of token IDs using the tagger/vocab Vocabulary.
// This is a basic implementation using whitespace tokenization.
func (t *Tokenizer) Encode(text string) ([]int, error) {
	if t.Vocabulary == nil {
		return nil, errors.New("tokenizer's vocabulary is not set")
	}

	tokenIDs, err := TokenizeAndConvertToIDs(text, t.Vocabulary, -1)
	if err != nil {
		return nil, err
	}

	return tokenIDs, nil
}

// TrainBPETokenizer is a convenience function that creates, trains, and saves
// a BPE tokenizer. Returns the path to the saved model.
func TrainBPETokenizer(projectRoot string, vocabSize int) (string, error) {
	bpe := NewBPETokenizer(vocabSize)

	bpe.AddSpecialToken("<|im_start|>")
	bpe.AddSpecialToken("<|im_end|>")
	bpe.AddSpecialToken("<pad>")
	bpe.AddSpecialToken("<s>")
	bpe.AddSpecialToken("</s>")
	bpe.AddSpecialToken("UNK")
	bpe.AddSpecialToken("\n")

	if err := bpe.Train(projectRoot); err != nil {
		return "", fmt.Errorf("BPE training failed: %w", err)
	}

	path := filepath.Join(projectRoot, "data/models/gob_models/bpe_tokenizer.gob")
	if err := bpe.Save(path); err != nil {
		return "", fmt.Errorf("BPE save failed: %w", err)
	}

	vocabPath := filepath.Join(projectRoot, "data/models/gob_models/bpe_vocabulary.gob")
	if err := bpe.Vocab.Save(vocabPath); err != nil {
		log.Printf("⚠️  BPE vocab save warning: %v", err)
	}

	log.Printf("✅ BPE Tokenizer saved to %s (vocab=%d, merges=%d)", path, bpe.Vocab.Size(), len(bpe.Merges))
	return path, nil
}

func isJSONPunct(s string) bool {
	if len(s) != 1 {
		return false
	}
	return strings.ContainsRune(`{}[],:"`, []rune(s)[0])
}

// protectPattern replaces spaces inside high-frequency phrases with
// a non-breaking space (U+00A0) or special boundary marker so the BPE
// encoder treats the entire sequence as a single atomic token unit.
func protectPattern(code, pattern string) string {
	if !strings.Contains(code, pattern) {
		return code
	}

	protected := strings.ReplaceAll(pattern, " ", "\u00A0")
	return strings.ReplaceAll(code, pattern, protected)
}

// tokenizeSource splits Go source code into tokens (preserving identifiers, keywords, operators).
func tokenizeSource(text string) []string {
	var tokens []string
	var current strings.Builder
	runes := []rune(text)

	flush := func() {
		if current.Len() > 0 {
			tokens = append(tokens, current.String())
			current.Reset()
		}
	}

	for _, r := range runes {
		if unicode.IsLetter(r) || unicode.IsDigit(r) || r == '_' {
			current.WriteRune(r)
		} else {
			flush()
			if !unicode.IsSpace(r) {

				tokens = append(tokens, string(r))
			}
		}
	}
	flush()
	return tokens
}

// tokenizeText splits natural language text into word tokens.
func tokenizeText(text string) []string {
	var tokens []string
	var current strings.Builder

	flush := func() {
		if current.Len() > 0 {
			word := strings.ToLower(current.String())
			if word != "" {
				tokens = append(tokens, word)
			}
			current.Reset()
		}
	}

	for _, r := range text {
		if unicode.IsLetter(r) || unicode.IsDigit(r) || r == '\'' || r == '_' {
			current.WriteRune(r)
		} else {
			flush()
			if !unicode.IsSpace(r) {
				tokens = append(tokens, string(r))
			}
		}
	}
	flush()
	return tokens
}

