func commonPrefix(ss []string) string {
	if len(ss) == 0 {
		return ""
	}
	p := ss[0]
	for _, s := range ss[1:] {
		for !strings.HasPrefix(s, p) {
			p = p[:len(p)-1]
			if p == "" {
				return ""
			}
		}
	}
	return p
}

// completePath completes a file path token.
func completePath(token string) []string {
	dir, prefix := filepath.Split(token)
	readDir := dir
	if readDir == "" {
		readDir = "."
	}
	entries, err := os.ReadDir(readDir)
	if err != nil {
		return nil
	}
	var out []string
	for _, e := range entries {
		name := e.Name()
		if !strings.HasPrefix(strings.ToLower(name), strings.ToLower(prefix)) {
			continue
		}
		if strings.HasPrefix(name, ".") && !strings.HasPrefix(prefix, ".") {
			continue
		}
		c := dir + name
		if e.IsDir() {
			c += "/"
		}
		out = append(out, c)
	}
	sort.Strings(out)
	return out
}

// copyModelParams copies src's parameter values into dst. Both models must
// share the architecture (same domain, same code); mismatched tensors are
// skipped defensively.
func copyModelParams(dst, src *seq2seq.Seq2Seq) {
	dp, sp := dst.Parameters(), src.Parameters()
	for i := range dp {
		if i < len(sp) && len(dp[i].Data) == len(sp[i].Data) {
			copy(dp[i].Data, sp[i].Data)
		}
	}
}

