// enableRawMode switches the terminal to raw mode (no echo, no line
// buffering, no signal chars) and returns a function restoring the
// original mode. ok is false when the fd isn't a terminal.
func enableRawMode(f *os.File) (func(), bool) {
	orig, err := tcgetattr(f)
	if err != nil {
		return nil, false
	}
	raw := *orig
	raw.Iflag &^= ignbrk | brkint | istrip | inlcr | igncr | icrnl | ixon
	raw.Oflag &^= opost
	raw.Lflag &^= echo | echonl | icanon | isig | iexten
	raw.Cflag &^= csize | parenb
	raw.Cflag |= cs8
	raw.Cc[vmin] = 1
	raw.Cc[vtime] = 0
	if err := tcsetattr(f, &raw); err != nil {
		return nil, false
	}
	return func() { tcsetattr(f, orig) }, true
}

// encodeInput tokenizes a question for the encoder: [ids...].
// Inputs are normalized the same way as at inference (see
// seq2seq.NormalizeQuery): punctuation variants of one phrasing share one
// encoding, so the model learns the intent once.
func encodeInput(tok *tokenizer.Tokenizer, q string) []int {
	ids, err := tok.Encode(seq2seq.NormalizeQuery(q))
	if err != nil {
		return nil
	}
	return ids
}

// encodeTarget tokenizes an answer for the decoder: [BOS, ids..., EOS].
func encodeTarget(tok *tokenizer.Tokenizer, v *vocab.Vocabulary, a string) []int {
	ids, err := tok.Encode(strings.ToLower(a))
	if err != nil {
		return nil
	}
	out := make([]int, 0, len(ids)+2)
	out = append(out, v.BosID)
	out = append(out, ids...)
	out = append(out, v.EosID)
	return out
}

// ensureGitHubRepo shallow-clones owner/repo into ~/workspace/codebase-maps
// (reused if already present) and returns the local directory.
func ensureGitHubRepo(rawURL string) (string, error) {
	if _, err := exec.LookPath("git"); err != nil {
		return "", fmt.Errorf("git isn't installed, so I can't clone %s", rawURL)
	}
	m := githubURL.FindStringSubmatch(rawURL)
	owner, repo := m[1], strings.TrimSuffix(m[2], ".git")
	url := rawURL
	if !strings.HasPrefix(strings.ToLower(url), "http") {
		url = "https://" + url
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	dest := filepath.Join(home, "workspace", "codebase-maps", owner+"-"+repo)
	if fi, err := os.Stat(dest); err == nil && fi.IsDir() {
		return dest, nil
	}
	fmt.Printf("[cloning %s (shallow)...]\n", url)
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
	defer cancel()
	cmd := exec.CommandContext(ctx, "git", "clone", "--depth", "1", url, dest)
	if out, err := cmd.CombinedOutput(); err != nil {
		return "", fmt.Errorf("clone failed: %v\n%s", err, strings.TrimSpace(string(out)))
	}
	return dest, nil
}

// expandBareNumber rewrites a lone "320" into the full issue/PR URL
// when the user just picked from a listed set of issues or PRs.
// Issue and PR numbers share one sequence per repo, so the number is
// unambiguous.
func expandBareNumber(line string) string {
	n := strings.TrimSpace(line)
	if !bareNumRe.MatchString(n) || len(lastList) == 0 {
		return line
	}
	for _, r := range lastList {
		if r.num == n {
			return fmt.Sprintf("https://github.com/%s/%s/%s/%s", r.owner, r.repo, r.kind, n)
		}
	}
	return line
}

// explainWithCodeIntent answers an explanation-seeking question by composing
// analyzer facts with neural prose. It returns ok=false when the symbol
// doesn't resolve, the model is unavailable, or the model produces nothing
// usable — callers fall back to the deterministic template.
func explainWithCodeIntent(p *analyze.Project, name, question, projectRoot string) (string, bool) {
	facts, ok := p.FactsForExplain(name, question)
	if !ok {
		return "", false
	}
	model := loadCodeIntentExplainer(projectRoot)
	if model == nil {
		return "", false
	}
	raw, err := model.Predict(facts.Input, 100)
	if err != nil || strings.TrimSpace(raw) == "" {
		return "", false
	}
	prose := extractProse(raw)
	if !prosePassesGate(prose, facts.Summary) {
		return "", false
	}
	var b strings.Builder
	b.WriteString(facts.Sig + "\n")
	b.WriteString("  " + facts.FileLine + "\n")
	b.WriteString("  " + facts.Summary + "\n")
	b.WriteString("\nIn plain words: " + prose + "\n")
	return b.String(), true
}

// extractAnalyzePath finds a filesystem path or GitHub URL in the message.
func extractAnalyzePath(line string) string {
	if m := quotedPath.FindStringSubmatch(line); m != nil {
		for _, g := range m[1:] {
			if g != "" {
				return g
			}
		}
	}
	if u := githubURL.FindString(line); u != "" {
		return u
	}
	lower := strings.ToLower(line)
	for _, phrase := range []string{"this project", "this repo", "this repository", "this codebase"} {
		if strings.Contains(lower, phrase) {
			return unifiedProjectRoot
		}
	}
	for _, tok := range strings.Fields(line) {
		clean := strings.TrimRight(tok, `.,;:!?`)

		clean = strings.TrimPrefix(clean, `"`)
		clean = strings.TrimPrefix(clean, `'`)
		clean = strings.TrimPrefix(clean, "(")
		clean = strings.TrimPrefix(clean, "[")
		clean = strings.TrimSuffix(clean, `"`)
		clean = strings.TrimSuffix(clean, `'`)
		clean = strings.TrimSuffix(clean, ")")
		clean = strings.TrimSuffix(clean, "]")
		if clean == "and/or" {
			continue
		}
		if strings.Contains(clean, "/") || strings.HasPrefix(clean, "~") {
			return clean
		}
	}
	return ""
}

// extractProse pulls the description lines from a codeintent model output.
// The trained format is Sig / file:line / description, so the first two
// non-empty lines are dropped (the model cannot copy them reliably; the
// analyzer's versions are used instead) and the rest become the prose.
func extractProse(raw string) string {
	var lines []string
	for _, ln := range strings.Split(strings.TrimSpace(raw), "\n") {
		if ln = strings.TrimSpace(ln); ln != "" {
			lines = append(lines, ln)
		}
	}
	if len(lines) > 2 {
		lines = lines[2:]
	}
	prose := strings.Join(lines, " ")
	if len(prose) > 600 {
		prose = prose[:600]
	}
	return strings.TrimSpace(prose)
}

// fetchIssue reads a public issue's title and body via the GitHub API.
// No auth: public issues only, which is all a beginner needs here.
func fetchIssue(owner, repo, num string) (*githubIssue, error) {
	ctx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
	defer cancel()
	req, err := http.NewRequestWithContext(ctx, "GET",
		fmt.Sprintf("https://api.github.com/repos/%s/%s/issues/%s", owner, repo, num), nil)
	if err != nil {
		return nil, err
	}
	req.Header.Set("User-Agent", "gollemer")
	req.Header.Set("Accept", "application/vnd.github+json")
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	if resp.StatusCode != 200 {
		return nil, fmt.Errorf("GitHub API: %s", resp.Status)
	}
	var issue githubIssue
	if err := json.NewDecoder(resp.Body).Decode(&issue); err != nil {
		return nil, err
	}
	return &issue, nil
}

