// isGoCliRequest reports whether the input asks to RUN a Go toolchain
// command. Concept questions about commands ("what does go mod tidy do",
// "how do you run one test in Go", "why did go test say cached") are
// GoDomain, not run requests. But "what go version do I have" IS a run
// request (it wants the output of `go version`), so have/has/installed
// questions are never carved out. The bare imperative "test my code" is
// a run request; the question "How do I test my code?" stays where the
// dataset put it (social) because the pattern is anchored to the bare
// imperative.
func isGoCliRequest(input string) bool {
	if isGoCommandQuestion(input) {
		return false
	}

	if gocliQuestionCarveout.MatchString(input) &&
		(goCommandLiteral.MatchString(input) || gocliIntent.MatchString(input)) &&
		!gocliHaveRequest.MatchString(input) &&
		goTerms.MatchString(input) {
		return false
	}
	return goCommandLiteral.MatchString(input) || gocliIntent.MatchString(input)
}

// isGoCommandQuestion reports whether the input asks what a Go command
// does ("what does go mod tidy do", "how do you run one test in Go").
// These are GoDomain concept questions, never run requests. A what/how
// question that merely names a command ("what go version do I have")
// stays a run request.
func isGoCommandQuestion(input string) bool {
	if !gocliQuestionCarveout.MatchString(input) {
		return false
	}
	if !goCommandLiteral.MatchString(input) && !runOneTestQuestion.MatchString(input) {
		return false
	}
	return gocliExplainMarker.MatchString(input) || runOneTestQuestion.MatchString(input)
}

// isMakeTarget reports whether name is a known Makefile target, including
// the chat entry points that are excluded from execution.
func isMakeTarget(name string) bool {
	if makeTargetsAllowlist[name] {
		return true
	}
	return name == "chat" || name == "debug-chat"
}

// isRunnableGoCommand reports whether a gocli reply is safe to offer for
// execution: a single go/gofmt invocation with no shell metacharacters.
func isRunnableGoCommand(reply string) bool {
	r := strings.TrimSpace(reply)
	return runnableGoCommand.MatchString(r) && !shellMetachars.MatchString(r)
}

// knowledgeTokens normalizes a query into matchable words.
func knowledgeTokens(s string) []string {
	s = strings.ToLower(s)
	words := goKnowledgeWord.FindAllString(s, -1)
	seen := map[string]bool{}
	out := make([]string, 0, len(words))
	for _, w := range words {
		if len(w) < 2 || seen[w] || knowledgeStopwords[w] {
			continue
		}
		seen[w] = true
		out = append(out, w)
	}
	return out
}

// latestCkptPaths returns the "latest weights" checkpoint pair. Unlike the
// best-weights checkpoint above, this one is banked every couple of epochs
// regardless of improvement, so a VM kill can never trap a run in a
// deterministic replay of the same non-improving epoch forever (2026-10-09:
// the codeintent run replayed epoch 71 nine times with byte-identical loss
// because the best-only gate never banked it). Resume prefers this file;
// the best-weights file stays the source of truth for final model selection.
func latestCkptPaths(projectRoot, domain string) (latestPath, latestMetaPath string) {
	modelPath := filepath.Join(projectRoot, "data", "models", "gob_models", "real_tiny_seq2seq_"+domain+".gob")
	return modelPath + ".latest", modelPath + ".latest.json"
}

// listIssues fetches the repo's open issues (excluding pull requests)
// and remembers them so the user can reply with just a number.
func listIssues(owner, repo string) string {
	var items []githubListItem
	err := githubGet(fmt.Sprintf("https://api.github.com/repos/%s/%s/issues?state=open&per_page=10", owner, repo), &items)
	if err != nil {
		return fmt.Sprintf("Couldn't list %s/%s issues: %s", owner, repo, err)
	}
	var refs []listedRef
	for _, it := range items {
		if len(it.PullRequest) > 0 {
			continue
		}
		refs = append(refs, listedRef{kind: "issues", owner: owner, repo: repo,
			num:	fmt.Sprint(it.Number), title: it.Title})
	}
	lastList = refs
	if len(refs) == 0 {
		return fmt.Sprintf("%s/%s has no open issues.", owner, repo)
	}
	var b strings.Builder
	fmt.Fprintf(&b, "Open issues in %s/%s:\n", owner, repo)
	for _, r := range refs {
		fmt.Fprintf(&b, "\n  #%s — %s", r.num, r.title)
	}
	b.WriteString("\n\nReply with the number, or paste the issue URL.")
	return b.String()
}

