// loadRecallPairs reads single-turn pairs for one domain from the
// training JSONL, keyed by normalized input. Multi-turn history-format
// inputs are skipped (they're model-input format, not raw messages).
// Last pair wins on duplicates: the dataset is append-ordered and
// newer pairs override older ones.
func loadRecallPairs(projectRoot, domain string) map[string]string {
	out := map[string]string{}
	raw, err := os.ReadFile(ChatDatasetPath(projectRoot))
	if err != nil {
		return out
	}
	var p struct {
		Input	string	`json:"input"`
		Output	string	`json:"output"`
		Domain	string	`json:"domain"`
	}
	for _, line := range strings.Split(string(raw), "\n") {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		p.Input, p.Output, p.Domain = "", "", ""
		if err := json.Unmarshal([]byte(line), &p); err != nil {
			continue
		}
		if p.Domain != domain || p.Input == "" || p.Output == "" {
			continue
		}
		if strings.HasPrefix(strings.ToLower(p.Input), "before you said ") {
			continue
		}
		key := normalizeRecallInput(p.Input)
		if key == "" {
			continue
		}
		out[key] = p.Output
	}
	return out
}

// loadSeedPairs reads Q&A pairs from a CSV file (header + rows).
// It replaces the old moe-dependent loader; only used when seeding
// a missing dataset from the built-in CSV.
func loadSeedPairs(dataPath string) ([]seedPair, error) {
	f, err := os.Open(dataPath)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	records, err := csv.NewReader(f).ReadAll()
	if err != nil {
		return nil, err
	}
	if len(records) < 2 {
		return nil, fmt.Errorf("seed dataset is empty")
	}
	pairs := make([]seedPair, 0, len(records)-1)
	for _, rec := range records[1:] {
		if len(rec) < 2 {
			continue
		}
		q, a := strings.TrimSpace(rec[0]), strings.TrimSpace(rec[1])
		if q == "" || a == "" {
			continue
		}
		pairs = append(pairs, seedPair{Q: q, A: a})
	}
	return pairs, nil
}

// loadTrainingCheckpoint restores a killed run's best weights for -resume.
// It refuses (returns an error) when the sidecar is missing or the
// vocabulary no longer matches, so a stale checkpoint can never corrupt a
// fresh run — the caller falls back to training from epoch 1.
func loadTrainingCheckpoint(tok *tokenizer.Tokenizer, curFP uint64, ckptPath, metaPath string) (*seq2seq.Seq2Seq, ckptMeta, error) {
	var meta ckptMeta
	data, err := os.ReadFile(metaPath)
	if err != nil {
		return nil, meta, fmt.Errorf("no checkpoint sidecar: %w", err)
	}
	if err := json.Unmarshal(data, &meta); err != nil {
		return nil, meta, fmt.Errorf("bad checkpoint sidecar: %w", err)
	}
	if meta.VocabFP != curFP {
		return nil, meta, fmt.Errorf("checkpoint vocab fingerprint %d != current %d: data changed, refusing resume", meta.VocabFP, curFP)
	}
	model, err := seq2seq.Load(ckptPath, tok)
	if err != nil {
		return nil, meta, fmt.Errorf("loading checkpoint weights: %w", err)
	}
	return model, meta, nil
}

// lrForDomain returns the base learning rate per domain. The 256/512
// codeintent model trains on very long code sequences; at that width the
// 1e-3 base LR tuned for smaller models lets the weights grow until a
// forward pass overflows to NaN (hit at epoch 24 on 2026-10-12: six
// LR-halving rollbacks could not recover because the batch order is fixed
// and the poisonous batch replayed identically). Halve the base LR for the
// big codeintent model only — the other 256/512 domains (gocode/go/gocli)
// train stably at 1e-3.
func lrForDomain(domain string) float32 {
	if domain == CodeIntentDomain || domain == CodeIntentBigDomain {
		return 5e-4
	}
	return realBaseLR
}

// makeBatches pads each bucket to its own max lengths.
func makeBatches(enc []encodedPair, size, padID int) []batch {
	var out []batch
	for i := 0; i < len(enc); i += size {
		end := i + size
		if end > len(enc) {
			end = len(enc)
		}
		grp := enc[i:end]
		maxIn, maxTg := 0, 0
		for _, p := range grp {
			if len(p.input) > maxIn {
				maxIn = len(p.input)
			}
			if len(p.target) > maxTg {
				maxTg = len(p.target)
			}
		}
		b := batch{}
		for _, p := range grp {
			in := make([]int, maxIn)
			copy(in, p.input)
			for k := len(p.input); k < maxIn; k++ {
				in[k] = padID
			}
			tg := make([]int, maxTg)
			copy(tg, p.target)
			for k := len(p.target); k < maxTg; k++ {
				tg[k] = padID
			}
			b.inputs = append(b.inputs, in)
			b.targets = append(b.targets, tg)
		}
		out = append(out, b)
	}
	return out
}

// makeTargetNames lists the Makefile targets the chat can run.
