func matchCandidates(pool []string, prefix string, fold bool) []string {
	var out []string
	for _, c := range pool {
		p, q := c, prefix
		if fold {
			p, q = strings.ToLower(c), strings.ToLower(prefix)
		}
		if strings.HasPrefix(p, q) {
			out = append(out, c)
		}
	}
	return out
}

// dimsForDomain returns (embeddingDim, hiddenDim) per domain. The gocode
// domain separates 24 near-identical code templates, so it gets a wider
// model; the gocli domain now separates ~40 near-identical commands, so it
// gets the same wider model. The go domain is the code-understanding
// brain: it learns the analyzer's intent/effect/why mappings, so it gets
// the wider model too. The MoE expert width scales as hiddenDim/2
// automatically. social/makefile keep their original dims so existing .gob
// checkpoints (which store their dims) stay valid and retraining stays
// comparable.
// maxTargetTokens bounds the output length per domain. Chat domains give
// short answers; the codeintent domain explains code and needs room.
func maxTargetTokens(domain string) int {
	if IsCodeIntentFamily(domain) {
		return 200
	}
	return 60
}

// normAugInput canonicalizes an input for collision detection: lowercase,
// punctuation dropped, whitespace collapsed. "I'm unhappy." and "i'm unhappy"
// are the same phrasing and must not carry different labels.
func normAugInput(s string) string {
	var b strings.Builder
	for _, r := range strings.ToLower(s) {
		if unicode.IsLetter(r) || unicode.IsDigit(r) || r == '\'' {
			b.WriteRune(r)
		} else if r == ' ' || r == '\t' {
			b.WriteRune(' ')
		}
	}
	return strings.Join(strings.Fields(b.String()), " ")
}

// normalizePairKey canonicalizes a pair for duplicate detection.
func normalizePairKey(p ChatPair) string {
	norm := func(s string) string {
		return strings.Join(strings.Fields(strings.ToLower(s)), " ")
	}
	return norm(p.Input) + "\n" + norm(p.Output)
}

// normalizeRecallInput lowercases, collapses whitespace, and strips
// trailing punctuation so "Have you ever played soccer?" matches the
// trained "have you ever played soccer".
func normalizeRecallInput(s string) string {
	s = strings.ToLower(strings.TrimSpace(s))
	s = strings.Join(strings.Fields(s), " ")
	s = strings.TrimRight(s, "?!.,")
	return strings.TrimSpace(s)
}

// offerRunGoCommand asks for confirmation, then runs a gocli command in
// the chat's working directory and prints its output. The answer is read
// through the chat's line reader so stdin stays on one reader.
func offerRunGoCommand(r *LineReader, cmd string) {
	cwd, _ := os.Getwd()
	if !stdinIsTerminal() {

		return
	}
	yn, err := r.ReadLine(fmt.Sprintf("[run it here? %s] [y/n]: ", cwd))
	if err != nil {
		fmt.Println("[cancelled]")
		return
	}
	yn = strings.ToLower(strings.TrimSpace(yn))
	if yn != "y" && yn != "yes" {
		fmt.Println("[not run]")
		return
	}
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Minute)
	defer cancel()

	fields := strings.Fields(cmd)
	out, err := exec.CommandContext(ctx, fields[0], fields[1:]...).CombinedOutput()
	if len(out) > 0 {
		fmt.Printf("%s", out)
	}
	if err != nil {
		fmt.Printf("[exit: %v]\n", err)
		return
	}
	fmt.Println("[done]")
}

// offerRunMakeCommand asks for confirmation, then runs a makefile target
// in the repo root with output streaming straight to the terminal.
// There is no timeout: long targets (make smarter, make eval) need
// their time, and the user confirmed interactively. Ctrl-C interrupts.
func offerRunMakeCommand(r *LineReader, projectRoot, target string) {
	if !stdinIsTerminal() {

		return
	}
	yn, err := r.ReadLine(fmt.Sprintf("[run it here? 'make %s'] [y/n]: ", target))
	if err != nil {
		fmt.Println("[cancelled]")
		return
	}
	yn = strings.ToLower(strings.TrimSpace(yn))
	if yn != "y" && yn != "yes" {
		fmt.Println("[not run]")
		return
	}
	fmt.Printf("[running: make %s — Ctrl-C to interrupt]\n", target)

	cmd := exec.Command("make", target)
	cmd.Dir = projectRoot
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		fmt.Printf("[exit: %v]\n", err)
		return
	}
	fmt.Println("[done]")
}

