// resolveAnalyzeRoot turns a user-supplied path or GitHub URL into a local
// directory: ~ is expanded, github.com URLs are shallow-cloned into
// ~/workspace/codebase-maps (cached between runs).
func resolveAnalyzeRoot(raw string) (string, error) {
	if githubURL.MatchString(raw) {
		return ensureGitHubRepo(raw)
	}
	path := raw
	if strings.HasPrefix(path, "~") {
		home, err := os.UserHomeDir()
		if err != nil {
			return "", fmt.Errorf("can't expand ~: %w", err)
		}
		path = filepath.Join(home, strings.TrimPrefix(path, "~"))
	}
	abs, err := filepath.Abs(path)
	if err != nil {
		return "", err
	}
	fi, err := os.Stat(abs)
	if err != nil {
		return "", fmt.Errorf("no such directory: %s", raw)
	}
	if !fi.IsDir() {
		return "", fmt.Errorf("%s is not a directory", raw)
	}
	return abs, nil
}

// routeDomain classifies a chat INPUT (not the output) into the domain
// model that should handle it. Used by unified chat. Tuned for perfect
// coverage on the training inputs: social, gocode, makefile, go, gocli.
// routeDomain routes a user message to its brain: the neural router
// first (when its model is trained), the hand-written regex rules as
// fallback. The deterministic answer layers (codebase Q&A, make
// commands, error help, issue lookup) run before the routed model is
// ever consulted, so the router only decides the neural fallback path.
func routeDomain(input string) string {
	if d, ok := routeNeural(unifiedProjectRoot, input); ok {
		return d
	}
	return routeDomainRegex(input)
}

// routeDomainRegex is the hand-written routing rules. It stays as the
// fallback when the neural router model is absent, and as the reference
// the neural router was trained to beat (45 misses on the training set).
func routeDomainRegex(input string) string {

	if gollemerDefinition.MatchString(input) {
		return SocialDomain
	}

	if makeExplain.MatchString(input) {
		return SocialDomain
	}

	if trainingDataQuestion.MatchString(input) {
		return SocialDomain
	}

	if analyzeIntent.MatchString(input) {
		return GoAnalyzeDomain
	}

	if analyzeVerb.MatchString(input) && extractAnalyzePath(input) != "" {
		return GoAnalyzeDomain
	}
	if makefileTerms.MatchString(input) || makefileIntent.MatchString(input) {
		return MakefileDomain
	}

	if isGoCommandQuestion(input) {
		return GoDomain
	}

	if isGoCliRequest(input) {
		return GoCliDomain
	}

	if goWorkflow.MatchString(input) {
		return GoDomain
	}

	if goStdlibQuestion.MatchString(input) {
		return GoDomain
	}

	if gocodeCodegen.MatchString(input) {
		return GocodeDomain
	}

	if goTerms.MatchString(input) {
		return GoDomain
	}

	if gocodeTerms.MatchString(input) {
		return GocodeDomain
	}
	return SocialDomain
}

// routeNeural classifies input with the trained router model. It returns
// ok=false when the model file is absent or unusable, or when the model
// emits something that is not a valid domain label — callers fall back
// to the regex router in all those cases.
func routeNeural(projectRoot, input string) (string, bool) {
	if projectRoot == "" {
		return "", false
	}
	routerModelState.Lock()
	defer routerModelState.Unlock()
	if routerModelState.root != projectRoot || (routerModelState.model == nil && routerModelState.err == nil) {
		m, err := loadRealModel(projectRoot, RouterDomain)
		routerModelState.root = projectRoot
		routerModelState.model = m
		routerModelState.err = err
		if err != nil {
			log.Printf("[ROUTER] no router model (%v); using regex fallback", err)
		}
	}
	if routerModelState.err != nil || routerModelState.model == nil {
		return "", false
	}
	out, _, err := routerModelState.model.PredictWithTrace(strings.ToLower(input), 8)
	if err != nil {
		return "", false
	}
	label := strings.ToLower(strings.TrimSpace(tidyDecode(out)))

	if !routerLabels[label] || strings.ContainsAny(label, " \t\n") {
		return "", false
	}
	return label, true
}

