// symbolNames lists function and type names from the last analyzed
// project, so "walk me through <tab>" completes real symbols.
func symbolNames() []string {
	p := lastAnalyzeProject
	if p == nil {
		return nil
	}
	seen := map[string]bool{}
	var out []string
	for _, pkg := range p.Packages {
		for _, fn := range pkg.Funcs {
			if fn.Name != "" && !seen[fn.Name] {
				seen[fn.Name] = true
				out = append(out, fn.Name)
			}
		}
		for _, t := range pkg.Types {
			if t.Name != "" && !seen[t.Name] {
				seen[t.Name] = true
				out = append(out, t.Name)
			}
		}
	}
	sort.Strings(out)
	return out
}

// synonymVariants returns up to n paraphrases of q, each swapping one word
// using the provided synonym map.
func synonymVariants(q string, n int, syns map[string][]string) []string {
	toks := tokenizeLower(q)
	var out []string
	for i, w := range toks {
		for _, syn := range syns[w] {
			nt := append([]string{}, toks...)
			nt[i] = syn
			out = append(out, strings.Join(nt, " "))
			if len(out) >= n {
				return out
			}
		}
	}
	return out
}

func tcgetattr(f *os.File) (*termios, error) {
	var t termios
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), tcgets, uintptr(unsafe.Pointer(&t)))
	if errno != 0 {
		return nil, errno
	}
	return &t, nil
}

func tcsetattr(f *os.File, t *termios) error {
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), tcsets, uintptr(unsafe.Pointer(t)))
	if errno != 0 {
		return errno
	}
	return nil
}

// termWidth returns the terminal width in columns, defaulting to 80.
func termWidth(f *os.File) int {
	var ws [4]uint16
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), tiocgwinsz, uintptr(unsafe.Pointer(&ws)))
	if errno != 0 || ws[1] == 0 {
		return 80
	}
	return int(ws[1])
}

// tidyDecode fixes the spacing the word-join decoder leaves around punctuation.
func tidyDecode(s string) string {
	for _, p := range []string{"?", "!", ".", ",", ":", ";", "'"} {
		s = strings.ReplaceAll(s, " "+p, p)
	}
	s = strings.ReplaceAll(s, "  ", " ")
	return strings.TrimSpace(s)
}

// tidyGoCode makes a generated snippet compile-shaped: it repairs the
// bracket/operator spacing the word-join decoder leaves ([ ] -> [], : = -> :=)
// and restores identifier case from the training data (fmt.Println, ...).
func tidyGoCode(s string, caseMap map[string]string) string {
	s = tidyDecode(s)
	for _, fix := range [][2]string{
		{"[ ]", "[]"}, {"( )", "()"},
		{": =", " :="}, {"= =", " =="}, {"! =", " !="},
		{"+ =", " +="}, {"- =", " -="}, {"* =", " *="}, {"/ =", " /="},
		{"< =", " <="}, {"> =", " >="},
	} {
		s = strings.ReplaceAll(s, fix[0], fix[1])
	}
	s = strings.ReplaceAll(s, "  ", " ")
	keys := make([]string, 0, len(caseMap))
	for k := range caseMap {
		keys = append(keys, k)
	}
	sort.Slice(keys, func(i, j int) bool { return len(keys[i]) > len(keys[j]) })
	for _, k := range keys {
		re := regexp.MustCompile(`\b` + regexp.QuoteMeta(k) + `\b`)
		s = re.ReplaceAllString(s, caseMap[k])
	}
	return s
}

// tidyGoCommand normalizes a predicted toolchain command: collapse
// whitespace runs, trim ends, and repair the tokenizer's punctuation
// splits ("go build ." must keep its space — "go build." would not
// execute — while "./..." and "fmt.Println" must be glued back).
// Unlike tidyDecode it never applies prose punctuation gluing.
func tidyGoCommand(s string) string {
	s = strings.Join(strings.Fields(s), " ")

	s = goCmdDotSlash.ReplaceAllString(s, " ./...")

	s = goCmdDottedWord.ReplaceAllString(s, "$1.$2")
	return strings.TrimSpace(s)
}

// tokenizeLower splits text exactly the way the tokenizer does
// (whitespace + {}[],:\"?!. as single-char tokens), lowercased so the
// model is case-insensitive. It must stay in sync with
// TokenizeAndConvertToIDs in internal/ai/neural/tokenizer.
func tokenizeLower(text string) []string {
	var toks []string
	runes := []rune(strings.ToLower(text))
	i := 0
	for i < len(runes) {
		r := runes[i]
		if r == ' ' || r == '\t' || r == '\n' || r == '\r' {
			i++
			continue
		}
		if strings.ContainsRune(`{}[],:\"?!.`, r) {
			toks = append(toks, string(r))
			i++
			continue
		}
		start := i
		for i < len(runes) && runes[i] != ' ' && runes[i] != '\t' && runes[i] != '\n' && runes[i] != '\r' && !strings.ContainsRune(`{}[],:\"`, runes[i]) {
			i++
		}
		if tok := string(runes[start:i]); tok != "" {
			toks = append(toks, tok)
		}
	}
	return toks
}

