// InferRepositoryStyle mines the coding conventions of the module
// containing the CodebaseContext's source directory.
func InferRepositoryStyle(codeCtx *CodebaseContext) (*RepoStyle, error) {
	if codeCtx == nil {
		return nil, fmt.Errorf("miner: nil CodebaseContext")
	}
	if codeCtx.SourceDir == "" {
		return nil, fmt.Errorf("miner: CodebaseContext has no SourceDir (load it with LoadPackageContext)")
	}
	_, pkgs, err := loadModulePackages(codeCtx.SourceDir)
	if err != nil {
		return nil, fmt.Errorf("miner: %w", err)
	}
	m := &styleMiner{tagCounts: make(map[string]int)}
	for _, p := range pkgs {
		if p == nil || p.TypesInfo == nil || len(p.Syntax) == 0 {
			continue
		}
		for _, f := range p.Syntax {
			if f == nil {
				continue
			}
			m.visitFile(f, p.TypesInfo)
		}
	}
	return m.style(), nil
}

// LoadPackageContext loads the Go package in dir with full type
// information and extracts its struct and interface metadata.
//
// The pattern is "." (exactly the package in dir); call once per
// directory for multi-package codebases. Package-level build or
// type-checking errors are collected from pkg.Errors and returned as a
// single descriptive error — no partial context is returned, so callers
// never silently generate from a broken type graph.
func LoadPackageContext(dir string) (*CodebaseContext, error) {
	absDir, err := filepath.Abs(dir)
	if err != nil {
		return nil, fmt.Errorf("ast: resolve dir %q: %w", dir, err)
	}
	cfg := &packages.Config{
		Mode: packages.NeedName |
			packages.NeedFiles |
			packages.NeedCompiledGoFiles |
