// extractInterface converts one *types.Interface declaration into
// metadata, rendering each method's full signature.
func extractInterface(tn *types.TypeName, iface *types.Interface,
	docs map[token.Pos]string, qf types.Qualifier) InterfaceMeta {

	im := InterfaceMeta{
		Name:		tn.Name(),
		DocComment:	docs[tn.Pos()],
		Methods:	[]MethodMeta{},
	}

	for i := 0; i < iface.NumMethods(); i++ {
		m := iface.Method(i)
		if m == nil {
			continue
		}
		sig, ok := m.Type().(*types.Signature)
		if !ok || sig == nil {
			continue
		}
		params, results := signatureStrings(sig, qf)
		im.Methods = append(im.Methods, MethodMeta{
			Name:		m.Name(),
			Parameters:	params,
			Results:	results,
			DocComment:	docs[m.Pos()],
		})
	}
	return im
}

// extractStruct converts one *types.Struct declaration into metadata,
// resolving each field's type string (with pointer indicators and
// package qualifiers), JSON tag, and doc comment.
func extractStruct(tn *types.TypeName, st *types.Struct,
	docs map[token.Pos]string, qf types.Qualifier) StructMeta {

	sm := StructMeta{
		Name:		tn.Name(),
		DocComment:	docs[tn.Pos()],
		Fields:		[]FieldMeta{},
	}
	for i := 0; i < st.NumFields(); i++ {
		f := st.Field(i)
		if f == nil {
			continue
		}
		var typeStr string
		if ft := f.Type(); ft != nil {
			typeStr = types.TypeString(ft, qf)
		}
		sm.Fields = append(sm.Fields, FieldMeta{
			Name:		f.Name(),
			TypeString:	typeStr,
			IsExported:	f.Exported(),
			JSONTag:	reflect.StructTag(st.Tag(i)).Get("json"),
			DocComment:	docs[f.Pos()],
		})
	}
	return sm
}

// fieldNamesInto collects every defined name in a field list by name,
// recursing into nested function types.
func fieldNamesInto(fl *ast.FieldList, into map[string]bool) {
	if fl == nil {
		return
	}
	for _, f := range fl.List {
		if f == nil {
			continue
		}
		for _, name := range f.Names {
			if name != nil && name.Name != "" {
				into[name.Name] = true
			}
		}
		if ft, ok := f.Type.(*ast.FuncType); ok && ft != nil {
			fieldNamesInto(ft.Params, into)
			fieldNamesInto(ft.Results, into)
		}
	}
}

// findModuleRoot walks up from dir to the directory containing go.mod.
func findModuleRoot(dir string) (string, error) {
	d, err := filepath.Abs(dir)
	if err != nil {
		return "", fmt.Errorf("resolve dir %q: %w", dir, err)
	}
	for {
		if _, serr := os.Stat(filepath.Join(d, "go.mod")); serr == nil {
			return d, nil
		}
		parent := filepath.Dir(d)
		if parent == d {
			return "", fmt.Errorf("no go.mod found above %q", dir)
		}
		d = parent
	}
}

// findTargetObject locates the symbol's object among a package's
// definitions. Bare symbols must be package-level; methods are matched
// by receiver type name because a method's *types.Func is not parented
// to the package scope.
func findTargetObject(p *packages.Package, recv, name string, isMethod bool) *impactTarget {
	scope := p.Types.Scope()
	for _, obj := range p.TypesInfo.Defs {
		if obj == nil || obj.Name() != name {
			continue
		}
		if isMethod {
			fn, ok := obj.(*types.Func)
			if !ok || methodReceiverName(fn) != recv {
				continue
			}
			return &impactTarget{obj: fn, name: name, kind: fmt.Sprintf("%T", fn), recv: recv, isMethod: true}
		}
		if obj.Parent() != scope {
			continue
		}
		return &impactTarget{obj: obj, name: name, kind: fmt.Sprintf("%T", obj)}
	}
	return nil
}

