// importAliases maps import path to the local package name written in
// source, honoring explicit aliases. Blank ("_") and dot (".") imports
// have no usable qualifier and are skipped.
func importAliases(files []*ast.File) map[string]string {
	aliases := make(map[string]string)
	for _, f := range files {
		if f == nil {
			continue
		}
		for _, imp := range f.Imports {
			if imp == nil || imp.Path == nil {
				continue
			}
			path, err := strconv.Unquote(imp.Path.Value)
			if err != nil || path == "" {
				continue
			}
			var name string
			if imp.Name != nil {
				name = imp.Name.Name
			}
			if name == "" {
				name = path
				if i := strings.LastIndex(path, "/"); i >= 0 {
					name = path[i+1:]
				}
			}
			if name == "_" || name == "." {
				continue
			}
			aliases[path] = name
		}
	}
	return aliases
}

// isContextType reports whether e denotes context.Context.
func isContextType(e ast.Expr, info *types.Info) bool {
	if e == nil || info == nil {
		return false
	}
	named, ok := info.TypeOf(e).(*types.Named)
	if !ok || named == nil || named.Obj() == nil || named.Obj().Pkg() == nil {
		return false
	}
	return named.Obj().Pkg().Path() == "context" && named.Obj().Name() == "Context"
}

func isGoIdent(s string) bool {
	if s == "" {
		return false
	}
	for i, r := range s {
		switch {
		case r == '_' || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z'):
		case i > 0 && r >= '0' && r <= '9':
