// makeQualifier returns a types.Qualifier that renders types from the
// loaded package unqualified and types from other packages with the
// local import name used in source (honoring explicit aliases such as
// `import js "encoding/json"`).
func makeQualifier(pkg *types.Package, aliases map[string]string) types.Qualifier {
	return func(other *types.Package) string {
		if other == nil || other == pkg {
			return ""
		}
		if name, ok := aliases[other.Path()]; ok && name != "" {
			return name
		}
		return other.Name()
	}
}

// methodReceiverName returns the named receiver type of a method,
// dereferencing pointers: "(*Store).Get" -> "Store".
func methodReceiverName(fn *types.Func) string {
	sig, ok := fn.Type().(*types.Signature)
	if !ok || sig.Recv() == nil {
		return ""
	}
	t := sig.Recv().Type()
	if ptr, ok := t.(*types.Pointer); ok {
		t = ptr.Elem()
	}
	if named, ok := t.(*types.Named); ok && named.Obj() != nil {
		return named.Obj().Name()
	}
	return ""
}

// methodSymbol renders "(*Server).Start" for pointer receivers and
// "Server.Start" for value receivers (including generic receivers like
// "Box[T].Get", where the base name is used).
func methodSymbol(fn *ast.FuncDecl) string {
	if fn.Recv == nil || len(fn.Recv.List) == 0 || fn.Recv.List[0] == nil {
		return fn.Name.Name
	}
	base := baseTypeName(fn.Recv.List[0].Type)
	if base == "" {
		return fn.Name.Name
	}
	if _, ok := fn.Recv.List[0].Type.(*ast.StarExpr); ok {
		return "(*" + base + ")." + fn.Name.Name
	}
	return base + "." + fn.Name.Name
}

// parseImpactSymbol splits "User" and "Store.Get" / "(*Store).Get"
// into receiver and name parts.
func parseImpactSymbol(s string) (recv, name string, isMethod bool, err error) {
	s = strings.TrimSpace(s)
	if i := strings.LastIndex(s, "."); i >= 0 {
		recv = strings.TrimSpace(s[:i])
		name = strings.TrimSpace(s[i+1:])
		recv = strings.Trim(recv, "()")
		recv = strings.TrimPrefix(recv, "*")
		isMethod = true
	} else {
		name = s
	}
	if !isGoIdent(name) || (isMethod && !isGoIdent(recv)) {
		return "", "", false, fmt.Errorf("impact: invalid symbol %q (want \"Name\" or \"Type.Method\")", s)
	}
	return recv, name, isMethod, nil
}

// referencesTarget reports whether obj is the target symbol. Object
// identity covers the common case; the fallback matches the same
// logical symbol across separate type-checkings (e.g. test variants),
// where identity does not hold. The kind check keeps a type distinct
// from a func/var of the same name.
func referencesTarget(obj types.Object, target *impactTarget) bool {
	if obj == nil {
		return false
	}
	if obj == target.obj {
		return true
	}
	if obj.Pkg() == nil || obj.Pkg().Path() != target.pkgPath {
		return false
	}
	if obj.Name() != target.name || fmt.Sprintf("%T", obj) != target.kind {
		return false
	}
	if target.isMethod {
		fn, ok := obj.(*types.Func)
		if !ok || methodReceiverName(fn) != target.recv {
			return false
		}
	}
	return true
}

// signatureStrings renders a signature's parameter and result lists.
// The final parameter of a variadic signature is rendered as "...T"
// rather than "[]T", matching how it is written in source.
func signatureStrings(sig *types.Signature, qf types.Qualifier) (params, results []string) {
	params = tupleStrings(sig.Params(), qf)
	if sig.Variadic() && sig.Params() != nil && sig.Params().Len() > 0 {
		last := sig.Params().At(sig.Params().Len() - 1)
		if last != nil {
			if slice, ok := last.Type().(*types.Slice); ok && slice != nil {
				var elem string
				if et := slice.Elem(); et != nil {
					elem = types.TypeString(et, qf)
				}
				name := ""
				if n := last.Name(); n != "" {
					name = n + " "
				}
				params[len(params)-1] = name + "..." + strings.TrimSpace(elem)
			}
		}
	}
	results = tupleStrings(sig.Results(), qf)
	return params, results
}

// skipFieldIdents marks every defined name in a field list (receiver
// names, parameter names, struct field names, interface method names)
// so they are not mistaken for references. It recurses into nested
// function types, whose parameter and result names are definitions too
// (e.g. interface method signatures).
func skipFieldIdents(skip map[*ast.Ident]bool, fl *ast.FieldList) {
	if fl == nil {
		return
	}
	for _, f := range fl.List {
		if f == nil {
			continue
		}
		for _, name := range f.Names {
			if name != nil {
				skip[name] = true
			}
		}
		if ft, ok := f.Type.(*ast.FuncType); ok && ft != nil {
			skipFieldIdents(skip, ft.Params)
			skipFieldIdents(skip, ft.Results)
		}
	}
}

// structTagKeys parses the keys of a raw struct tag literal,
// e.g. `json:"name" db:"id"` -> ["json", "db"].
func structTagKeys(tag string) []string {
	unquoted, err := strconv.Unquote(tag)
	if err != nil {
		return nil
	}
	var keys []string
	for {
		unquoted = strings.TrimLeft(unquoted, " ")
		if unquoted == "" {
			break
		}
		i := strings.Index(unquoted, ":")
		if i <= 0 {
			break
		}
		key := unquoted[:i]
		rest := unquoted[i+1:]
		if !strings.HasPrefix(rest, "\"") {
			break
		}
		j := 1
		for j < len(rest) {
			if rest[j] == '\\' {
				j += 2
				continue
			}
			if rest[j] == '"' {
				break
			}
			j++
		}
		if j >= len(rest) {
			break
		}
		keys = append(keys, key)
		unquoted = rest[j+1:]
	}
	return keys
}

// errorStyle picks the winning style by plurality; ties prefer the
// stdlib-only style, so %w or pkg/errors are only recommended when
// they are the clear habit.
func (m *styleMiner) errorStyle() string {
	best, style := m.stdErr, ErrorStyleStandard
	if m.fmtWrap > best {
		best, style = m.fmtWrap, ErrorStyleFmtWrap
	}
	if m.pkgErrors > best {
		best, style = m.pkgErrors, ErrorStylePkgErrors
	}
	return style
}

// style assembles the final RepoStyle from the observations.
func (m *styleMiner) style() *RepoStyle {
	tags := make([]string, 0, len(m.tagCounts))
	for key := range m.tagCounts {
		tags = append(tags, key)
	}
	sort.Slice(tags, func(i, j int) bool {
		if m.tagCounts[tags[i]] != m.tagCounts[tags[j]] {
			return m.tagCounts[tags[i]] > m.tagCounts[tags[j]]
		}
		return tags[i] < tags[j]
	})
	var density float64
	if m.exportedIdents > 0 {
		density = float64(m.documented) / float64(m.exportedIdents)
	}
	var usesCtx bool
	if m.exportedFuncs > 0 {
		usesCtx = float64(m.ctxFuncs)/float64(m.exportedFuncs) >= 0.5
	}
	return &RepoStyle{
		ErrorHandlingStyle:	m.errorStyle(),
		CommonStructTags:	tags,
		UsesContext:		usesCtx,
		DocCommentDensity:	density,
	}
}

// visitCallExpr classifies error creation/wrapping calls using
// type-checked package paths, so import aliases resolve correctly.
func (m *styleMiner) visitCallExpr(c *ast.CallExpr, info *types.Info) {
	if c == nil || info == nil {
		return
	}
	sel, ok := c.Fun.(*ast.SelectorExpr)
	if !ok || sel == nil || sel.Sel == nil {
		return
	}
	fn, ok := info.Uses[sel.Sel].(*types.Func)
	if !ok || fn == nil || fn.Pkg() == nil {
		return
	}
	switch {
	case fn.Pkg().Path() == "fmt" && fn.Name() == "Errorf":
		if callWraps(c) {
			m.fmtWrap++
		} else {
			m.stdErr++
		}
	case fn.Pkg().Path() == "errors" && (fn.Name() == "New" || fn.Name() == "Join"):
		m.stdErr++
	case fn.Pkg().Path() == "github.com/pkg/errors":
		m.pkgErrors++
	}
}

func (m *styleMiner) visitFile(f *ast.File, info *types.Info) {
	ast.Inspect(f, func(n ast.Node) bool {
		switch n := n.(type) {
		case *ast.FuncDecl:
			m.visitFuncDecl(n, info)
		case *ast.GenDecl:
			m.visitGenDecl(n)
		case *ast.StructType:
			m.visitStructType(n)
		case *ast.CallExpr:
			m.visitCallExpr(n, info)
		}
		return true
	})
}

// visitFuncDecl records context.Context usage and doc comments for
// exported functions and methods.
func (m *styleMiner) visitFuncDecl(d *ast.FuncDecl, info *types.Info) {
	if d == nil || d.Name == nil || !d.Name.IsExported() {
		return
	}
	m.exportedFuncs++
	m.exportedIdents++
	if d.Doc != nil {
		m.documented++
	}

	if d.Type != nil && d.Type.Params != nil && len(d.Type.Params.List) > 0 {
		if isContextType(d.Type.Params.List[0].Type, info) {
			m.ctxFuncs++
		}
	}
}

// visitGenDecl records doc comments for exported package-level types,
// consts, vars, and exported struct fields.
func (m *styleMiner) visitGenDecl(d *ast.GenDecl) {
	if d == nil {
		return
	}
	for _, spec := range d.Specs {
		switch s := spec.(type) {
		case *ast.TypeSpec:
			if s == nil || s.Name == nil || !s.Name.IsExported() {
				continue
			}
			m.exportedIdents++
			if s.Doc != nil || d.Doc != nil {
				m.documented++
			}
			if st, ok := s.Type.(*ast.StructType); ok {
				m.visitStructFieldsDocs(st)
			}
		case *ast.ValueSpec:
			if s == nil {
				continue
			}
			for _, name := range s.Names {
				if name == nil || !name.IsExported() {
					continue
				}
				m.exportedIdents++
				if s.Doc != nil || d.Doc != nil {
					m.documented++
				}
			}
		}
	}
}

// visitStructFieldsDocs counts exported struct fields and their doc
// comments (go/doc shows trailing line comments as field docs).
func (m *styleMiner) visitStructFieldsDocs(st *ast.StructType) {
	if st == nil || st.Fields == nil {
		return
	}
	for _, field := range st.Fields.List {
		if field == nil {
			continue
		}
		for _, name := range field.Names {
			if name == nil || !name.IsExported() {
				continue
			}
			m.exportedIdents++
			if field.Doc != nil || field.Comment != nil {
				m.documented++
			}
		}
	}
}

// visitStructType aggregates struct tag keys across the module.
func (m *styleMiner) visitStructType(st *ast.StructType) {
	if st == nil || st.Fields == nil {
		return
	}
	for _, field := range st.Fields.List {
		if field == nil || field.Tag == nil {
			continue
		}
		for _, key := range structTagKeys(field.Tag.Value) {
			m.tagCounts[key]++
		}
	}
}

// tupleStrings renders a parameter or result tuple as "name type" for
// named entries and the bare type string for unnamed ones.
func tupleStrings(t *types.Tuple, qf types.Qualifier) []string {
	out := []string{}
	if t == nil {
		return out
	}
	for i := 0; i < t.Len(); i++ {
		v := t.At(i)
		if v == nil {
			continue
		}
		var typeStr string
		if vt := v.Type(); vt != nil {
			typeStr = types.TypeString(vt, qf)
		}
		if name := v.Name(); name != "" {
			out = append(out, name+" "+strings.TrimSpace(typeStr))
		} else {
			out = append(out, typeStr)
		}
	}
	return out
}

