// checkFinalCompiles type-checks the tuned program as a standalone
// package. It mirrors pkg/beginner's compile gate so the pipeline
// never returns code that does not build.
func checkFinalCompiles(fset *token.FileSet, file *ast.File) error {
	var first error
	cfg := types.Config{
		Importer:	importer.Default(),
		Error: func(e error) {
			if first == nil {
				first = e
			}
		},
	}
	_, _ = cfg.Check("pipeline", fset, []*ast.File{file}, nil)
	return first
}

// cleanStepDesc drops a description that merely echoes the title
// ("Main — calls worker." for title "Main" becomes "calls worker").
func cleanStepDesc(desc, title string) string {
	desc = strings.TrimSpace(desc)
	if desc == "" {
		return ""
	}
	if strings.HasPrefix(desc, title) {
		desc = strings.TrimSpace(strings.TrimPrefix(desc, title))
		desc = strings.TrimPrefix(desc, "—")
		desc = strings.TrimPrefix(desc, "-")
		desc = strings.TrimSpace(desc)
	}

	if strings.Trim(desc, ".!") == "" {
		return ""
	}
	return desc
}

func cleanStepTitle(title string) string {
	return strings.TrimSpace(stepPrefix.ReplaceAllString(title, ""))
}

// diagramArrow is the │/▼ connector, centered under a box.
func diagramArrow() string {
	c := strings.Repeat(" ", diagramWidth/2+1)
	return c + "│\n" + c + "▼"
}

// diagramBox draws a titled box of fixed inner width. When outlet is
// true the bottom border carries a ┬ where the next arrow continues.
func diagramBox(title string, rows []string, outlet bool) string {
	var b strings.Builder
	bar := strings.Repeat("─", diagramWidth)
	b.WriteString("┌" + bar + "┐\n")
	b.WriteString("│" + padCenter(title, diagramWidth) + "│\n")
	b.WriteString("├" + bar + "┤\n")
	for _, r := range rows {
		b.WriteString("│" + padRight(r, diagramWidth) + "│\n")
	}
	if outlet {
		b.WriteString("└" + strings.Repeat("─", diagramWidth/2) + "┬" +
			strings.Repeat("─", diagramWidth/2-1) + "┘")
	} else {
		b.WriteString("└" + bar + "┘")
	}
	return b.String()
}

// formatDelta renders the allocation summary in allocs/op terms.
func formatDelta(before, after int) string {
	if before == after {
		return fmt.Sprintf("No unbounded allocations found — already at %d allocs/op", after)
	}
	return fmt.Sprintf("Reduced allocations from %d to %d allocs/op", before, after)
}

// hasGoStatement reports whether code launches a goroutine: any
// line whose first token is the go keyword.
func hasGoStatement(code string) bool {
	for _, line := range strings.Split(code, "\n") {
		if strings.HasPrefix(strings.TrimSpace(line), "go ") {
			return true
		}
	}
	return false
}

func isGoIdentifier(s string) bool {
	if s == "" {
		return false
	}
	for i, r := range s {
		if r != '_' && !unicode.IsLetter(r) && (i == 0 || !unicode.IsDigit(r)) {
			return false
		}
	}
	return true
}

// padCenter centers s in w columns.
func padCenter(s string, w int) string {
	s = truncateRunes(s, w)
	n := utf8.RuneCountInString(s)
	left := (w - n) / 2
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", w-n-left)
}

// padRight pads s to w columns, counting runes (box-drawing chars are
// multibyte). Overlong strings are truncated cleanly.
func padRight(s string, w int) string {
	s = truncateRunes(s, w)
	return s + strings.Repeat(" ", w-utf8.RuneCountInString(s))
}

// pipelineFileName labels the generated file for trace output. It
// prefers the codebase package name when it is a valid Go identifier.
func pipelineFileName(codeCtx *gast.CodebaseContext) string {
	if codeCtx != nil && isGoIdentifier(codeCtx.PackageName) {
		return codeCtx.PackageName + ".go"
	}
	return "pipeline.go"
}

// plainDelta rewrites the tuner's metric into plain words.
func plainDelta(d string) string {
	lower := strings.ToLower(d)
	if strings.Contains(lower, "no unbounded allocations") || strings.Contains(lower, "already at 0") {
		return "already lean — the tuner found nothing to trim."
	}
	return d
}

// provingLine is the real stage-2 outcome for the diagram.
func provingLine(r *PipelineResult) string {
	if r.IsSafetyVerified {
		return "0 nil-panics, 0 leaks              ✓"
	}
	return "needs a human read-through      ⚠"
}

// truncateRunes shortens s to at most n runes, adding … when cut.
func truncateRunes(s string, n int) string {
	if utf8.RuneCountInString(s) <= n {
		return s
	}
	r := []rune(s)
	return strings.TrimSpace(string(r[:n-1])) + "…"
}

// tuningLine is the real stage-3 outcome for the diagram.
func tuningLine(r *PipelineResult) string {
	if d := strings.TrimSpace(r.PerformanceDelta); d != "" {
		return truncateRunes(plainDelta(d), 44)
	}
	return "code already lean"
}

// zeroNilAndLeakViolations reports whether the safety report contains
// no unchecked nil dereferences and no missing resource defers.
// Other warning categories (e.g. slice-bounds risk) do not fail the
// proof; they are advisory.
func zeroNilAndLeakViolations(report *analysis.SafetyReport) bool {
	if report == nil {
		return false
	}
	for _, v := range report.Violations {
		switch v.Category {
		case analysis.CategoryCriticalNilDereference, analysis.CategoryResourceLeakWarning:
			return false
		}
	}
	return true
}

// LooksLikeGoError reports whether the line looks like a pasted Go
// compiler error, vet finding, or panic — as opposed to a chat
// question. It is deliberately conservative: a false negative just
// means the normal router handles the line.
func LooksLikeGoError(line string) bool {
	t := strings.ToLower(strings.TrimSpace(line))
	if t == "" {
		return false
	}
	if fileLineRe.MatchString(t) {
		return true
	}
	for _, m := range errorMarkers {
		if strings.Contains(t, m) {
			return true
		}
	}
	return false
}

// Translate matches one error line against the pattern table and
// returns the plain-words help. It reports false when nothing matches,
// so the caller can fall back to the language model.
func Translate(line string) (Help, bool) {
	trimmed := strings.TrimSpace(line)
	for _, p := range patterns {
		if m := p.re.FindStringSubmatch(trimmed); m != nil {
			var meaning, fix string
			if p.custom != nil {
				meaning, fix = p.custom(m)
			} else {
				expand := func(tmpl string) string {
					out := tmpl
					for i, g := range m[1:] {
						out = strings.ReplaceAll(out, "$"+strconv.Itoa(i+1), g)
					}
					return out
				}
				meaning, fix = expand(p.meaning), expand(p.fix)
			}
			return Help{
				Title:		p.title,
				Meaning:	meaning,
				Fix:		fix,
				Matched:	trimmed,
			}, true
		}
	}
	return Help{}, false
}

