// CosineSimilarity returns the cosine of the angle between a and b. It
// is 0 for dimension mismatches, empty vectors, and zero vectors, and
// the result is clamped to [-1, 1] against float error.
func CosineSimilarity(a, b []float32) float32 {
	if len(a) != len(b) || len(a) == 0 {
		return 0
	}
	var dot, na, nb float64
	for i := range a {
		x, y := float64(a[i]), float64(b[i])
		dot += x * y
		na += x * x
		nb += y * y
	}
	if na == 0 || nb == 0 {
		return 0
	}
	s := dot / (math.Sqrt(na) * math.Sqrt(nb))
	if s > 1 {
		return 1
	}
	if s < -1 {
		return -1
	}
	return float32(s)
}

// EmbedText returns the L2-normalized hashed bag-of-words embedding of
// text. It returns nil for non-positive dim. The empty text maps to
// the zero vector.
func EmbedText(text string, dim int) []float32 {
	if dim <= 0 {
		return nil
	}
	v := make([]float32, dim)
	for _, tok := range wordTokens(text) {
		h := fnv.New32a()
		_, _ = h.Write([]byte(tok))
		v[h.Sum32()%uint32(dim)]++
	}
	var norm float64
	for _, x := range v {
		norm += float64(x) * float64(x)
	}
	if norm == 0 {
		return v
	}
	norm = math.Sqrt(norm)
	for i := range v {
		v[i] = float32(float64(v[i]) / norm)
	}
	return v
}

// GetNode returns the node with the given ID.
func (g *KnowledgeGraph) GetNode(id string) (CodeNode, bool) {
	if g == nil {
		return CodeNode{}, false
	}
	g.mu.RLock()
	defer g.mu.RUnlock()
	n, ok := g.Nodes[id]
	return n, ok
}

// SetEmbedding attaches a vector embedding to a node. The slice is
// copied. It is a no-op for unknown IDs or a nil graph.
func (g *KnowledgeGraph) SetEmbedding(id string, emb []float32) {
	if g == nil {
		return
	}
	g.mu.Lock()
	defer g.mu.Unlock()
	n, ok := g.Nodes[id]
	if !ok {
		return
	}
	cp := make([]float32, len(emb))
	copy(cp, emb)
	n.Embedding = cp
	g.Nodes[id] = n
}

