// FormatLLMFeedback converts the metrics into structured prompt
// feedback for an LLM optimization pass.
func (m *BenchmarkMetrics) FormatLLMFeedback() string {
	if m == nil {
		return ""
	}
	var b strings.Builder
	b.WriteString("Benchmark Performance Report:\n")
	if !m.Passed {
		b.WriteString("- Result: FAILED (metrics may be incomplete)\n")
	}
	fmt.Fprintf(&b, "- Speed: %g ns/op\n", m.NsPerOp)
	fmt.Fprintf(&b, "- Memory: %d B/op across %d allocations\n", m.AllocBytesPerOp, m.AllocsPerOp)
	if m.AllocsPerOp > 0 {
		b.WriteString("Recommendation: optimize memory allocation by avoiding slice re-allocations or heap escapes.\n")
	} else {
		b.WriteString("Recommendation: no allocations detected; allocation behavior is already optimal.\n")
	}
	return b.String()
}

// CreateSandbox builds an isolated copy of the targetDir module with
// the given files applied on top (candidates win on conflicts), and
// returns the sandbox directory plus a cleanup function that removes
// it. Unlike ValidateGeneratedCode it does not run anything; the
// caller owns execution (e.g. benchmark validation).
func CreateSandbox(targetDir string, candidateFiles map[string]string) (sandboxDir string, cleanup func(), err error) {
	if targetDir == "" {
		return "", nil, fmt.Errorf("runner: empty targetDir")
	}
	info, err := os.Stat(targetDir)
	if err != nil {
		return "", nil, fmt.Errorf("runner: targetDir: %w", err)
	}
	if !info.IsDir() {
		return "", nil, fmt.Errorf("runner: targetDir %q is not a directory", targetDir)
	}
	if _, err := os.Stat(filepath.Join(targetDir, "go.mod")); err != nil {
