// safeJoin joins a candidate-relative path onto the sandbox, rejecting
// absolute paths and ".." escapes so generated content can never be
// written outside the sandbox.
func safeJoin(sandbox, rel string) (string, error) {
	if rel == "" {
		return "", fmt.Errorf("empty path")
	}
	if filepath.IsAbs(rel) {
		return "", fmt.Errorf("absolute paths not allowed")
	}
	clean := filepath.Clean(rel)
	if clean == ".." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
		return "", fmt.Errorf("path escapes sandbox")
	}
	return filepath.Join(sandbox, clean), nil
}

// splitTestOutput unwraps `go test -json` events into human-readable
// text and harvests the names of failed tests (including subtests).
// Non-JSON lines and stderr are passed through verbatim.
func splitTestOutput(stdout, stderr string) (string, map[string]bool) {
	var sb strings.Builder
	failed := make(map[string]bool)
	for _, line := range strings.Split(stdout, "\n") {
		if strings.TrimSpace(line) == "" {
			continue
		}
		var ev testEvent
		if err := json.Unmarshal([]byte(line), &ev); err != nil {
			sb.WriteString(line)
			sb.WriteByte('\n')
			continue
		}
		if ev.Action == "fail" && ev.Test != "" {
			failed[ev.Test] = true
		}
		if ev.Output != "" {
			sb.WriteString(ev.Output)
		}
	}
	if s := strings.TrimSpace(stderr); s != "" {
		sb.WriteString(s)
		sb.WriteByte('\n')
	}
	return sb.String(), failed
}

// truncate caps output length; parsed Errors carry the details.
func truncate(s string) string {
	if len(s) <= maxOutputBytes {
		return s
	}
	return s[:maxOutputBytes] + "\n[output truncated]"
}

// CalculateFitness scores a candidate: +50 for passing tests, +20 for
// compiling with no syntax/compiler errors, minus 2 per allocation
// per op and minus ns/op divided by 1000. Nil arguments contribute
// nothing.
func CalculateFitness(res *runner.ExecutionResult, bench *runner.BenchmarkMetrics) float64 {
	score := 0.0
	if res != nil {
		if res.Passed {
			score += 50
		}
		compilesClean := true
		for _, e := range res.Errors {
			if e.Category == runner.CategoryCompiler || e.Category == runner.CategorySyntax {
				compilesClean = false
				break
			}
		}
		if compilesClean {
			score += 20
		}
	}
	if bench != nil {
		score -= float64(bench.AllocsPerOp) * 2
		score -= bench.NsPerOp / 1000
	}
	return score
}

