		fmt.Printf("cannot open logs/edits/edits.log: %v\n", err)
		os.Exit(1)
	}
	defer f.Close()
	s := bufio.NewScanner(f)
	total := 0
	parsed := 0
	success := 0
	for s.Scan() {
		line := s.Text()
		var r rectr
		if err := json.Unmarshal([]byte(line), &r); err != nil {
			continue
		}
		total++
