func countPatternSavings(files []string, plain, goTok *tokenizer.BPETokenizer) []patternSaving {
	patterns := tokenizer.GoHighFreqTokens()
	var results []patternSaving

	for _, p := range patterns {
		if len(p) < 5 {
			continue
		}
		totalSavings := 0
		fileCount := 0
		for _, path := range files {
			data, err := os.ReadFile(path)
			if err != nil {
				continue
			}
			content := string(data)
			count := strings.Count(content, p)
			if count > 0 {

				savings := count * 3
				totalSavings += savings
				fileCount++
			}
		}
		if totalSavings > 0 {
			results = append(results, patternSaving{
				pattern:	p,
				savings:	totalSavings,
				files:		fileCount,
			})
		}
	}

	for i := 0; i < len(results); i++ {
		for j := i + 1; j < len(results); j++ {
			if results[j].savings > results[i].savings {
				results[i], results[j] = results[j], results[i]
			}
		}
	}

	return results
}

func extractTokens(obj interface{}, counter map[string]int) {
	switch v := obj.(type) {
	case map[string]interface{}:
		for k, val := range v {
			counter[k]++
			extractTokens(val, counter)
		}
	case []interface{}:
		for _, item := range v {
			extractTokens(item, counter)
		}
	default:
		token := fmt.Sprintf("%v", v)
		counter[token]++
	}
}

func findMissing(obj interface{}, vocab map[string]int, missing map[string]int) {
	switch v := obj.(type) {
	case map[string]interface{}:
		for k, val := range v {
			if _, exists := vocab[k]; !exists {
				missing[k]++
			}
			findMissing(val, vocab, missing)
		}
	case []interface{}:
		for _, item := range v {
			findMissing(item, vocab, missing)
		}
	default:
		token := fmt.Sprintf("%v", v)
		if _, exists := vocab[token]; !exists {
			missing[token]++
		}
	}
}

func findTensors(v reflect.Value, totalParams *int, tensorCount *int) {
	if !v.IsValid() {
		return
	}

	if v.Type() == reflect.TypeOf(&tensor.Tensor{}) && !v.IsNil() {
		t := v.Interface().(*tensor.Tensor)
		*tensorCount++
		*totalParams += len(t.Data)
		return
	}

	switch v.Kind() {
	case reflect.Ptr, reflect.Interface:
		if !v.IsNil() {
			findTensors(v.Elem(), totalParams, tensorCount)
		}
	case reflect.Struct:
		for i := 0; i < v.NumField(); i++ {
			findTensors(v.Field(i), totalParams, tensorCount)
		}
	case reflect.Slice, reflect.Array:
		for i := 0; i < v.Len(); i++ {
			findTensors(v.Index(i), totalParams, tensorCount)
		}
	case reflect.Map:
		for _, key := range v.MapKeys() {
			findTensors(v.MapIndex(key), totalParams, tensorCount)
		}
	}
}

func flattenSemanticOutput(semanticOutput map[string]interface{}) (string, error) {
	var parts []string

	if op, ok := semanticOutput["operation"].(string); ok {
		parts = append(parts, "operation:"+op)
	}

	if resource, ok := semanticOutput["target_resource"].(map[string]interface{}); ok {
		if resType, ok := resource["type"].(string); ok {

			resType = strings.ReplaceAll(resType, "::", "_")
			parts = append(parts, "type:"+resType)
		}
		if name, ok := resource["name"].(string); ok {
			parts = append(parts, "name:"+name)
		}

		if properties, ok := resource["properties"].(map[string]interface{}); ok {
			for key, value := range properties {
				parts = append(parts, fmt.Sprintf("%s:%v", key, value))
			}
		}
	}

	if context, ok := semanticOutput["context"].(map[string]interface{}); ok {
		for key, value := range context {
			parts = append(parts, fmt.Sprintf("%s:%v", key, value))
		}
	}

	return strings.Join(parts, " "), nil
}

func randomChoice(list []string) string {
	return list[rand.Intn(len(list))]
}

func randomChoices(list []string, n int) []string {
	result := make([]string, n)
	for i := range n {
		result[i] = randomChoice(list)
	}
	return result
}

func truncatePath(path string, maxLen int) string {
	if len(path) <= maxLen {
		return path
	}
	return "..." + path[len(path)-maxLen+3:]
}

func truncateString(s string, maxLen int) string {
	if len(s) <= maxLen {
		return s
	}
	return s[:maxLen-3] + "..."
}

